INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$14037904$SATQ$, $SATQ$de2230bc-eaa2-456f-89fd-f7fa5b5e0a65$SATQ$::uuid, $SATQ$31928d17-0f75-4bb6-9af7-6cc790d1546c$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li><em>The Heartbeat of Wounded Knee: Native America from 1890 to the Present</em> is a history book by Ojibwe author David Treuer.</li>
<li>In a review, a critic for <em>The Economist</em> noted that &ldquo;Treuer&rsquo;s storytelling skills shine&rdquo; and that the book is an &ldquo;elegant handling of [a] complex narrative.&rdquo;</li>
<li>A critic for<em> O, The Oprah Magazine </em>called it &ldquo;a marvel of research and storytelling.&rdquo;</li>
<li>A critic for<em> </em>the<em> Missoulian</em> dubbed it &ldquo;a monumental achievement.&rdquo;</li>
</ul>$SATQ$, $SATQ$<p>The student wants to emphasize a similarity in how critics responded to Treuer&rsquo;s book. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"5783715b-b52d-46e2-9956-e89a3c404620","content":"<p>Treuer&rsquo;s book, which was widely reviewed, focuses on Native American history from 1890 to the present.</p>"},{"id":"fc5a1099-a796-4835-87cd-8f0acd5783cb","content":"<p>Dubbed &ldquo;a monumental achievement&rdquo; by the<em> Missoulian</em>, Treuer&rsquo;s book documents over a century of Native American history.</p>"},{"id":"685c5529-a06c-4b48-8660-1fac226d7d2a","content":"<p>Critics praised Treuer&rsquo;s book for its compelling narrative, with <em>O, The Oprah Magazine </em>calling it &ldquo;a marvel of research and storytelling&rdquo; and <em>The Economist</em> likewise writing that &ldquo;Treuer&rsquo;s storytelling skills shine&rdquo; and that the book is an &ldquo;elegant handling of [a] complex narrative.&rdquo;</p>"},{"id":"95e55327-efdd-4c0e-b619-702e675469eb","content":"<p>While the<em> Missoulian</em> focused on the book&rsquo;s broader achievement, <em>The Economist</em> zeroed in on Treuer&rsquo;s storytelling skills.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["685c5529-a06c-4b48-8660-1fac226d7d2a"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The sentence emphasizes a similarity in how critics responded to Treuer&rsquo;s book, noting that the critics for <em>O, The Oprah Magazine</em>&nbsp;and&nbsp;<em>The Economist</em> both praised the book&rsquo;s storytelling. </p><p>Choice A is incorrect. The sentence provides background information about Treuer&rsquo;s book; it doesn&rsquo;t emphasize a similarity in how critics responded to it. Choice B is incorrect. The sentence cites a single critic&rsquo;s response to Treuer&rsquo;s book; it doesn&rsquo;t emphasize a similarity in the responses of multiple critics. Choice D is incorrect. The sentence emphasizes a difference, not a similarity, in how two critics responded to Treuer&rsquo;s book. </p>$SATQ$, false, 0, $SATQ$OSP-710-SYN$SATQ$, $SATQ$$SATQ$, $SATQ$e351d661-04a9-43bf-b982-a909b4ce23fa$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"14037904","external_id":"de2230bc-eaa2-456f-89fd-f7fa5b5e0a65","vaultid":"31928d17-0f75-4bb6-9af7-6cc790d1546c","uId":"4b933eb0-2d8b-4600-8eb8-130819378a00","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li><em>The Heartbeat of Wounded Knee: Native America from 1890 to the Present</em> is a history book by Ojibwe author David Treuer.</li>\n<li>In a review, a critic for <em>The Economist</em> noted that &ldquo;Treuer&rsquo;s storytelling skills shine&rdquo; and that the book is an &ldquo;elegant handling of [a] complex narrative.&rdquo;</li>\n<li>A critic for<em> O, The Oprah Magazine </em>called it &ldquo;a marvel of research and storytelling.&rdquo;</li>\n<li>A critic for<em> </em>the<em> Missoulian</em> dubbed it &ldquo;a monumental achievement.&rdquo;</li>\n</ul>","stem":"<p>The student wants to emphasize a similarity in how critics responded to Treuer&rsquo;s book. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"5783715b-b52d-46e2-9956-e89a3c404620","content":"<p>Treuer&rsquo;s book, which was widely reviewed, focuses on Native American history from 1890 to the present.</p>"},{"id":"fc5a1099-a796-4835-87cd-8f0acd5783cb","content":"<p>Dubbed &ldquo;a monumental achievement&rdquo; by the<em> Missoulian</em>, Treuer&rsquo;s book documents over a century of Native American history.</p>"},{"id":"685c5529-a06c-4b48-8660-1fac226d7d2a","content":"<p>Critics praised Treuer&rsquo;s book for its compelling narrative, with <em>O, The Oprah Magazine </em>calling it &ldquo;a marvel of research and storytelling&rdquo; and <em>The Economist</em> likewise writing that &ldquo;Treuer&rsquo;s storytelling skills shine&rdquo; and that the book is an &ldquo;elegant handling of [a] complex narrative.&rdquo;</p>"},{"id":"95e55327-efdd-4c0e-b619-702e675469eb","content":"<p>While the<em> Missoulian</em> focused on the book&rsquo;s broader achievement, <em>The Economist</em> zeroed in on Treuer&rsquo;s storytelling skills.</p>"}],"keys":["685c5529-a06c-4b48-8660-1fac226d7d2a"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The sentence emphasizes a similarity in how critics responded to Treuer&rsquo;s book, noting that the critics for <em>O, The Oprah Magazine</em>&nbsp;and&nbsp;<em>The Economist</em> both praised the book&rsquo;s storytelling. </p><p>Choice A is incorrect. The sentence provides background information about Treuer&rsquo;s book; it doesn&rsquo;t emphasize a similarity in how critics responded to it. Choice B is incorrect. The sentence cites a single critic&rsquo;s response to Treuer&rsquo;s book; it doesn&rsquo;t emphasize a similarity in the responses of multiple critics. Choice D is incorrect. The sentence emphasizes a difference, not a similarity, in how two critics responded to Treuer&rsquo;s book. </p>","parenttemplatename":"OSP-710-SYN","parenttemplateid":"","templateclusterid":"e351d661-04a9-43bf-b982-a909b4ce23fa","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959348,"updateDate":1691007959348}$SATQ$::jsonb, 1691007959348, 1691007959348),
    ($SATQ$146233fc$SATQ$, $SATQ$bbe9b69c-8e7c-479f-b587-c98e3d5291d6$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Lighthouses send out crucial light signals to help ships and other watercraft navigate at night.</li>
<li>Before automation, lighthouses were run by lighthouse keepers.</li>
<li>Maria Younghans was the lighthouse keeper at Biloxi Light in Mississippi.</li>
<li>She held this position from <span data-ssml-say-as="date">1867</span> to <span data-ssml-say-as="date">1918</span>.</li>
<li>Flora McNeil was the lighthouse keeper at Bridgeport Breakwater Light in Connecticut.</li>
<li>She held this position from <span data-ssml-say-as="date">1904</span> to <span data-ssml-say-as="date">1920</span>.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to emphasize the order in which the two lighthouse keepers began their careers. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"e4dc2ea0-0d24-46c0-a2c6-c55ab955fc43","content":"<p>From <span data-ssml-say-as=\"date\">1867</span> to <span data-ssml-say-as=\"date\">1918</span>, the nighttime waters of Mississippi were more navigable thanks to lighthouse keepers Flora McNeil and Maria Younghans.</p>"},{"id":"a49055ab-3073-479d-a83d-08a57d3a4458","content":"<p>Before automation, lighthouse keepers like Maria Younghans and Flora McNeil were crucial to ensuring safe navigation for watercraft.</p>"},{"id":"bd6b6b0c-1543-4e57-9893-2701968a22e1","content":"<p>Flora McNeil began her career as a lighthouse keeper years after Maria Younghans did.</p>"},{"id":"7de91f6a-f2dc-4e7f-9cbb-0e66dab1f734","content":"<p>Maria Younghans&rsquo;s career as a lighthouse keeper ended in <span data-ssml-say-as=\"date\">1918</span>, whereas Flora McNeil&rsquo;s ended in <span data-ssml-say-as=\"date\">1920</span>.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["bd6b6b0c-1543-4e57-9893-2701968a22e1"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The sentence emphasizes the order in which the two lighthouse keepers began their careers, noting that McNeil, who became the keeper at Bridgeport Breakwater Light in 1904, began her career years after Younghans, who became the keeper at Biloxi Light in 1867.</p><p>Choice A is incorrect because it makes a generalization about the effects of McNeil&rsquo;s and Younghans&rsquo;s work; it doesn&rsquo;t emphasize the order in which the two keepers began their careers. In addition, the sentence misrepresents information from the notes; McNeil was the keeper at a lighthouse in Connecticut from 1904 to 1920, not at a lighthouse in Mississippi from 1867 to 1918. Choice B is incorrect. The sentence claims that Younghans and McNeil were crucial to ensuring the safety of watercraft before lighthouses became automated; it doesn&rsquo;t emphasize the order in which the two keepers began their careers. Choice D is incorrect. The sentence emphasizes when the lighthouse keepers&rsquo; respective careers ended; it doesn&rsquo;t emphasize the order in which the two keepers began their careers.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"146233fc","external_id":"bbe9b69c-8e7c-479f-b587-c98e3d5291d6","vaultid":null,"uId":"47aa606f-5091-4a9b-9e69-7d6b98c3fd01","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Lighthouses send out crucial light signals to help ships and other watercraft navigate at night.</li>\n<li>Before automation, lighthouses were run by lighthouse keepers.</li>\n<li>Maria Younghans was the lighthouse keeper at Biloxi Light in Mississippi.</li>\n<li>She held this position from <span data-ssml-say-as=\"date\">1867</span> to <span data-ssml-say-as=\"date\">1918</span>.</li>\n<li>Flora McNeil was the lighthouse keeper at Bridgeport Breakwater Light in Connecticut.</li>\n<li>She held this position from <span data-ssml-say-as=\"date\">1904</span> to <span data-ssml-say-as=\"date\">1920</span>.</li>\n</ul>","stem":"<p>The student wants to emphasize the order in which the two lighthouse keepers began their careers. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"e4dc2ea0-0d24-46c0-a2c6-c55ab955fc43","content":"<p>From <span data-ssml-say-as=\"date\">1867</span> to <span data-ssml-say-as=\"date\">1918</span>, the nighttime waters of Mississippi were more navigable thanks to lighthouse keepers Flora McNeil and Maria Younghans.</p>"},{"id":"a49055ab-3073-479d-a83d-08a57d3a4458","content":"<p>Before automation, lighthouse keepers like Maria Younghans and Flora McNeil were crucial to ensuring safe navigation for watercraft.</p>"},{"id":"bd6b6b0c-1543-4e57-9893-2701968a22e1","content":"<p>Flora McNeil began her career as a lighthouse keeper years after Maria Younghans did.</p>"},{"id":"7de91f6a-f2dc-4e7f-9cbb-0e66dab1f734","content":"<p>Maria Younghans&rsquo;s career as a lighthouse keeper ended in <span data-ssml-say-as=\"date\">1918</span>, whereas Flora McNeil&rsquo;s ended in <span data-ssml-say-as=\"date\">1920</span>.</p>"}],"keys":["bd6b6b0c-1543-4e57-9893-2701968a22e1"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The sentence emphasizes the order in which the two lighthouse keepers began their careers, noting that McNeil, who became the keeper at Bridgeport Breakwater Light in 1904, began her career years after Younghans, who became the keeper at Biloxi Light in 1867.</p><p>Choice A is incorrect because it makes a generalization about the effects of McNeil&rsquo;s and Younghans&rsquo;s work; it doesn&rsquo;t emphasize the order in which the two keepers began their careers. In addition, the sentence misrepresents information from the notes; McNeil was the keeper at a lighthouse in Connecticut from 1904 to 1920, not at a lighthouse in Mississippi from 1867 to 1918. Choice B is incorrect. The sentence claims that Younghans and McNeil were crucial to ensuring the safety of watercraft before lighthouses became automated; it doesn&rsquo;t emphasize the order in which the two keepers began their careers. Choice D is incorrect. The sentence emphasizes when the lighthouse keepers&rsquo; respective careers ended; it doesn&rsquo;t emphasize the order in which the two keepers began their careers.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1755117061191,"updateDate":1755117061191}$SATQ$::jsonb, 1755117061191, 1755117061191),
    ($SATQ$1469d23a$SATQ$, $SATQ$97dd449e-ce8b-4a14-8699-2fe5bb0768fe$SATQ$::uuid, $SATQ$113e5b27-9fe2-44b1-85b3-7c7d7181af1e$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Etel Adnan was a Lebanese American poet and artist known for making many leporellos.</li>
<li>A leporello is an artist&rsquo;s book that is folded accordion style.</li>
<li>When the book is expanded, the artist&rsquo;s work is revealed, and its zigzag shape allows it to stand on its own.</li>
<li>Her leporello <em>December from My Window </em>(1993) features a panoramic landscape.</li>
<li>It is painted using ink and watercolor.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to describe Adnan&rsquo;s <em>December from My Window</em> to an audience already familiar with leporellos. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"d5e48463-1e4f-43b2-8b9c-9a1725c279a2","content":"<p>Featuring a panoramic landscape, the 1993 work is one of Adnan&rsquo;s many leporellos, which are accordion-style folded books that when expanded reveal the artist&rsquo;s work.</p>"},{"id":"b8bddfbb-53e9-4222-b7fa-235f59dea767","content":"<p>When expanded, Adnan&rsquo;s 1993 leporello <em>December from My Window</em> reveals a panoramic landscape painted in ink and watercolor.</p>"},{"id":"4e5f65a4-2a27-498f-8e73-e637c481592c","content":"<p>Known for making many other accordion-style folded books called leporellos, Adnan created <em>December from My Window</em> in 1993.</p>"},{"id":"6678a26f-a5a0-4387-8ae6-234f1ad1e5d5","content":"<p>A leporello, such as Adnan&rsquo;s <em>December from My Window</em>, is folded accordion style, and due to its zigzag shape it is able to stand on its own when fully expanded.&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["b8bddfbb-53e9-4222-b7fa-235f59dea767"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. This choice describes Adnan&rsquo;s <em>December from My Window</em> in a way that assumes the audience is already familiar with leporellos and focuses on the specific features of the work&mdash;its content and medium. </p><p>Choice A is incorrect. This choice isn&rsquo;t suited for an audience already familiar with leporellos. A familiar audience wouldn&rsquo;t need to have the term defined or explained. Choice C is incorrect. This choice doesn&rsquo;t describe Adnan&rsquo;s <em>December from My Window</em>. It mentions the year and the type of work but not the content or the medium. In addition, it provides a simple definition of leporellos, making this an inappropriate choice for an audience already familiar with leporellos. Choice D is incorrect. This choice isn&rsquo;t suited for an audience already familiar with leporellos. A familiar audience wouldn&rsquo;t need to have the term defined. </p>$SATQ$, false, 0, $SATQ$OSP-KA-SYN-M005$SATQ$, $SATQ$$SATQ$, $SATQ$c48408ee-0d91-4cc6-accb-40244c2c9005$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"1469d23a","external_id":"97dd449e-ce8b-4a14-8699-2fe5bb0768fe","vaultid":"113e5b27-9fe2-44b1-85b3-7c7d7181af1e","uId":"b9ce0161-313e-4c31-9873-f094af82d32a","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Etel Adnan was a Lebanese American poet and artist known for making many leporellos.</li>\n<li>A leporello is an artist&rsquo;s book that is folded accordion style.</li>\n<li>When the book is expanded, the artist&rsquo;s work is revealed, and its zigzag shape allows it to stand on its own.</li>\n<li>Her leporello <em>December from My Window </em>(1993) features a panoramic landscape.</li>\n<li>It is painted using ink and watercolor.</li>\n</ul>","stem":"<p>The student wants to describe Adnan&rsquo;s <em>December from My Window</em> to an audience already familiar with leporellos. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"d5e48463-1e4f-43b2-8b9c-9a1725c279a2","content":"<p>Featuring a panoramic landscape, the 1993 work is one of Adnan&rsquo;s many leporellos, which are accordion-style folded books that when expanded reveal the artist&rsquo;s work.</p>"},{"id":"b8bddfbb-53e9-4222-b7fa-235f59dea767","content":"<p>When expanded, Adnan&rsquo;s 1993 leporello <em>December from My Window</em> reveals a panoramic landscape painted in ink and watercolor.</p>"},{"id":"4e5f65a4-2a27-498f-8e73-e637c481592c","content":"<p>Known for making many other accordion-style folded books called leporellos, Adnan created <em>December from My Window</em> in 1993.</p>"},{"id":"6678a26f-a5a0-4387-8ae6-234f1ad1e5d5","content":"<p>A leporello, such as Adnan&rsquo;s <em>December from My Window</em>, is folded accordion style, and due to its zigzag shape it is able to stand on its own when fully expanded.&nbsp;</p>"}],"keys":["b8bddfbb-53e9-4222-b7fa-235f59dea767"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. This choice describes Adnan&rsquo;s <em>December from My Window</em> in a way that assumes the audience is already familiar with leporellos and focuses on the specific features of the work&mdash;its content and medium. </p><p>Choice A is incorrect. This choice isn&rsquo;t suited for an audience already familiar with leporellos. A familiar audience wouldn&rsquo;t need to have the term defined or explained. Choice C is incorrect. This choice doesn&rsquo;t describe Adnan&rsquo;s <em>December from My Window</em>. It mentions the year and the type of work but not the content or the medium. In addition, it provides a simple definition of leporellos, making this an inappropriate choice for an audience already familiar with leporellos. Choice D is incorrect. This choice isn&rsquo;t suited for an audience already familiar with leporellos. A familiar audience wouldn&rsquo;t need to have the term defined. </p>","parenttemplatename":"OSP-KA-SYN-M005","parenttemplateid":"","templateclusterid":"c48408ee-0d91-4cc6-accb-40244c2c9005","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959372,"updateDate":1691007959372}$SATQ$::jsonb, 1691007959372, 1691007959372),
    ($SATQ$164a32e7$SATQ$, $SATQ$387d0434-4979-45b3-bb93-5ca85b2968cd$SATQ$::uuid, $SATQ$5343acb6-2f55-4dcf-954a-0e650d4d5935$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Claude McKay (1889&ndash;1948) was a Jamaican American writer.</li>
<li><em>Songs of Jamaica</em> (1912) and <em>Constab Ballads</em> (1912) are two acclaimed poetry collections that McKay published while living in Jamaica.</li>
<li>McKay moved to Harlem in New York City in 1914.</li>
<li>He is best known as a poet and novelist of the Harlem Renaissance, a literary and cultural movement of the 1920s and 1930s.</li>
<li>His most famous works include the poetry collection <em>Harlem Shadows</em> (1922) and the novel <em>Home to Harlem</em> (1928).</li>
</ul>$SATQ$, $SATQ$<p>The student wants to emphasize Claude McKay&rsquo;s accomplishments before moving to Harlem. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"8239c159-ec69-43e3-ac79-c6d3f619a1d7","content":"<p>Jamaican American writer Claude McKay is the author of works such as <em>Songs of Jamaica</em> (1912), <em>Constab Ballads</em> (1912), <em>Harlem Shadows</em> (1922), and <em>Home to Harlem</em> (1928).</p>"},{"id":"85f5cd0e-1e54-484a-823e-be939dba5331","content":"<p>Although he is best known as a Harlem Renaissance writer, Claude McKay had published two acclaimed poetry collections in 1912 while living in Jamaica: <em>Songs of Jamaica</em> and <em>Constab Ballads</em>.</p>"},{"id":"4893f8c6-a02d-4f22-a74e-7c103c6668f3","content":"<p>In 1914, Claude McKay moved to Harlem, where he would become known as a poet and novelist of the Harlem Renaissance (a literary and cultural movement of the 1920s and 1930s).</p>"},{"id":"fc6a5467-5c04-4b04-ab68-4e41c5f070c7","content":"<p>Before moving to Harlem, Claude McKay&mdash;author of the poetry collection <em>Harlem Shadows</em> (1922) and the novel <em>Home to Harlem</em> (1928)&mdash;lived in Jamaica.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["85f5cd0e-1e54-484a-823e-be939dba5331"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. This choice contrasts McKay&rsquo;s fame as a Harlem Renaissance writer with his earlier achievements as a Jamaican poet, and it names the two collections he published before moving to Harlem. </p><p>Choice A is incorrect. This choice doesn&rsquo;t emphasize McKay&rsquo;s accomplishments before moving to Harlem. It lists some of his works but doesn&rsquo;t distinguish between those he wrote in Jamaica and those he wrote in Harlem. Choice C is incorrect. This choice doesn&rsquo;t emphasize McKay&rsquo;s accomplishments before moving to Harlem. It only mentions the year he moved and what he would become known for afterwards. Choice D is incorrect. This choice doesn&rsquo;t emphasize McKay&rsquo;s accomplishments before moving to Harlem. It mentions that he lived in Jamaica, but it doesn&rsquo;t name any of the works he published there. </p>$SATQ$, false, 0, $SATQ$OSP-KA-SYN-M006$SATQ$, $SATQ$$SATQ$, $SATQ$1a19b454-08bd-45ff-89a4-74cfbcb78d3c$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"164a32e7","external_id":"387d0434-4979-45b3-bb93-5ca85b2968cd","vaultid":"5343acb6-2f55-4dcf-954a-0e650d4d5935","uId":"85f9fc60-8b4c-43e4-9d0c-46418f417c14","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Claude McKay (1889&ndash;1948) was a Jamaican American writer.</li>\n<li><em>Songs of Jamaica</em> (1912) and <em>Constab Ballads</em> (1912) are two acclaimed poetry collections that McKay published while living in Jamaica.</li>\n<li>McKay moved to Harlem in New York City in 1914.</li>\n<li>He is best known as a poet and novelist of the Harlem Renaissance, a literary and cultural movement of the 1920s and 1930s.</li>\n<li>His most famous works include the poetry collection <em>Harlem Shadows</em> (1922) and the novel <em>Home to Harlem</em> (1928).</li>\n</ul>","stem":"<p>The student wants to emphasize Claude McKay&rsquo;s accomplishments before moving to Harlem. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"8239c159-ec69-43e3-ac79-c6d3f619a1d7","content":"<p>Jamaican American writer Claude McKay is the author of works such as <em>Songs of Jamaica</em> (1912), <em>Constab Ballads</em> (1912), <em>Harlem Shadows</em> (1922), and <em>Home to Harlem</em> (1928).</p>"},{"id":"85f5cd0e-1e54-484a-823e-be939dba5331","content":"<p>Although he is best known as a Harlem Renaissance writer, Claude McKay had published two acclaimed poetry collections in 1912 while living in Jamaica: <em>Songs of Jamaica</em> and <em>Constab Ballads</em>.</p>"},{"id":"4893f8c6-a02d-4f22-a74e-7c103c6668f3","content":"<p>In 1914, Claude McKay moved to Harlem, where he would become known as a poet and novelist of the Harlem Renaissance (a literary and cultural movement of the 1920s and 1930s).</p>"},{"id":"fc6a5467-5c04-4b04-ab68-4e41c5f070c7","content":"<p>Before moving to Harlem, Claude McKay&mdash;author of the poetry collection <em>Harlem Shadows</em> (1922) and the novel <em>Home to Harlem</em> (1928)&mdash;lived in Jamaica.</p>"}],"keys":["85f5cd0e-1e54-484a-823e-be939dba5331"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. This choice contrasts McKay&rsquo;s fame as a Harlem Renaissance writer with his earlier achievements as a Jamaican poet, and it names the two collections he published before moving to Harlem. </p><p>Choice A is incorrect. This choice doesn&rsquo;t emphasize McKay&rsquo;s accomplishments before moving to Harlem. It lists some of his works but doesn&rsquo;t distinguish between those he wrote in Jamaica and those he wrote in Harlem. Choice C is incorrect. This choice doesn&rsquo;t emphasize McKay&rsquo;s accomplishments before moving to Harlem. It only mentions the year he moved and what he would become known for afterwards. Choice D is incorrect. This choice doesn&rsquo;t emphasize McKay&rsquo;s accomplishments before moving to Harlem. It mentions that he lived in Jamaica, but it doesn&rsquo;t name any of the works he published there. </p>","parenttemplatename":"OSP-KA-SYN-M006","parenttemplateid":"","templateclusterid":"1a19b454-08bd-45ff-89a4-74cfbcb78d3c","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959372,"updateDate":1691007959372}$SATQ$::jsonb, 1691007959372, 1691007959372),
    ($SATQ$16631d34$SATQ$, $SATQ$66c2a748-013a-438c-a079-b62142b6633d$SATQ$::uuid, $SATQ$a8a80919-32fd-4b89-9b13-e5be26f0256c$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>The Million Song Dataset (MSD) includes main audio features and descriptive tags for popular songs.</li>
<li>Audio features include acoustic traits such as loudness and pitch intervals.</li>
<li>Many algorithms use these audio features to predict a new song&rsquo;s popularity.</li>
<li>These algorithms may fail to accurately identify main audio features of a song with varying acoustic traits.</li>
<li>Algorithms based on descriptive tags that describe fixed traits such as genre are more reliable predictors of song popularity.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to explain a disadvantage of relying on audio features to predict a song&rsquo;s popularity. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"bbc21e6b-5a27-4fcc-a39c-8b8040321067","content":"<p>Many popularity-predicting algorithms are based on a song&rsquo;s audio features, such as loudness and pitch intervals.</p>"},{"id":"6b98382a-ffca-46a4-9e48-0043f166c531","content":"<p>Algorithms based on audio features may misidentify the main features of a song with varying acoustic traits, making such algorithms less reliable predictors of popularity than those based on fixed traits.</p>"},{"id":"0c5b3ceb-ea9c-4c6d-97b5-69029cced36d","content":"<p>Audio features describe acoustic traits such as pitch intervals, which may vary within a song, whereas descriptive tags describe fixed traits such as genre, which are reliable predictors of popularity.</p>"},{"id":"492a1512-cfc8-480f-9d25-5fc4c72f592a","content":"<p>The MSD&rsquo;s descriptive tags are reliable predictors of a song&rsquo;s popularity, as the traits they describe are fixed.</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["6b98382a-ffca-46a4-9e48-0043f166c531"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. This choice uses relevant information from the notes to explain a disadvantage of relying on audio features to predict a song&rsquo;s popularity&mdash;namely, that it may misidentify features of certain songs. It also contrasts audio features with descriptive tags, which are more reliable predictors. </p><p>Choice A is incorrect. This choice only states a fact about the algorithms without evaluating their reliability or accuracy. Choice C is incorrect. This choice only describes the difference between audio features and descriptive tags without indicating why this difference matters for predicting popularity. Choice D is incorrect. This choice only mentions descriptive tags, which are not the focus of the student&rsquo;s rhetorical goal. </p>$SATQ$, false, 0, $SATQ$OSP-KA-SYN-H006$SATQ$, $SATQ$$SATQ$, $SATQ$853062e6-05a9-40e3-a765-0ca76dbffb3e$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"16631d34","external_id":"66c2a748-013a-438c-a079-b62142b6633d","vaultid":"a8a80919-32fd-4b89-9b13-e5be26f0256c","uId":"0ea7fff8-ff71-4e5d-a2b2-4c295723ef62","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>The Million Song Dataset (MSD) includes main audio features and descriptive tags for popular songs.</li>\n<li>Audio features include acoustic traits such as loudness and pitch intervals.</li>\n<li>Many algorithms use these audio features to predict a new song&rsquo;s popularity.</li>\n<li>These algorithms may fail to accurately identify main audio features of a song with varying acoustic traits.</li>\n<li>Algorithms based on descriptive tags that describe fixed traits such as genre are more reliable predictors of song popularity.</li>\n</ul>","stem":"<p>The student wants to explain a disadvantage of relying on audio features to predict a song&rsquo;s popularity. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"bbc21e6b-5a27-4fcc-a39c-8b8040321067","content":"<p>Many popularity-predicting algorithms are based on a song&rsquo;s audio features, such as loudness and pitch intervals.</p>"},{"id":"6b98382a-ffca-46a4-9e48-0043f166c531","content":"<p>Algorithms based on audio features may misidentify the main features of a song with varying acoustic traits, making such algorithms less reliable predictors of popularity than those based on fixed traits.</p>"},{"id":"0c5b3ceb-ea9c-4c6d-97b5-69029cced36d","content":"<p>Audio features describe acoustic traits such as pitch intervals, which may vary within a song, whereas descriptive tags describe fixed traits such as genre, which are reliable predictors of popularity.</p>"},{"id":"492a1512-cfc8-480f-9d25-5fc4c72f592a","content":"<p>The MSD&rsquo;s descriptive tags are reliable predictors of a song&rsquo;s popularity, as the traits they describe are fixed.</p>"}],"keys":["6b98382a-ffca-46a4-9e48-0043f166c531"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. This choice uses relevant information from the notes to explain a disadvantage of relying on audio features to predict a song&rsquo;s popularity&mdash;namely, that it may misidentify features of certain songs. It also contrasts audio features with descriptive tags, which are more reliable predictors. </p><p>Choice A is incorrect. This choice only states a fact about the algorithms without evaluating their reliability or accuracy. Choice C is incorrect. This choice only describes the difference between audio features and descriptive tags without indicating why this difference matters for predicting popularity. Choice D is incorrect. This choice only mentions descriptive tags, which are not the focus of the student&rsquo;s rhetorical goal. </p>","parenttemplatename":"OSP-KA-SYN-H006","parenttemplateid":"","templateclusterid":"853062e6-05a9-40e3-a765-0ca76dbffb3e","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959372,"updateDate":1691007959372}$SATQ$::jsonb, 1691007959372, 1691007959372),
    ($SATQ$176edca6$SATQ$, $SATQ$330ea545-cb02-4e1a-a12b-6bb6afc1c7fe$SATQ$::uuid, $SATQ$ee0f7049-9016-4d3f-a493-d41d97125d70$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>A 2017 study of sign language learners tested the role of iconicity&mdash;the similarity of a sign to the thing it represents&mdash;in language acquisition. The study found that the<strong> </strong>greater the iconicity of a sign, the more likely it was to have been learned. <span aria-hidden="true">______</span><span class="sr-only">blank</span> the correlation between acquisition and iconicity was lower than that between acquisition and another factor studied: sign frequency.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"17763e49-0cb0-46b4-9aaa-8e0a85d14c89","content":"<p>In fact,</p>"},{"id":"393d4b8a-31b7-4cb6-a685-69373420cfbb","content":"<p>In other words,</p>"},{"id":"83c1b541-9190-4fda-9185-83502ad9fb9f","content":"<p>Granted,</p>"},{"id":"16463f5d-0df2-4ddb-91e1-a1aefcc9f938","content":"<p>As a result,</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["83c1b541-9190-4fda-9185-83502ad9fb9f"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. &ldquo;Granted&rdquo; logically signals that the following information&mdash;that iconicity is not as highly correlated with acquisition as sign frequency&mdash;is true in spite of the information about the correlation between iconicity and acquisition in the previous sentence. </p><p>Choice A is incorrect because &ldquo;in fact&rdquo; illogically signals that the sentence that follows either emphasizes or refutes the information in the previous sentence regarding the correlation between iconicity and acquisition. Instead, the sentence that follows provides additional information that is true in spite of the preceding information; it neither emphasizes nor refutes that information. Choice B is incorrect because &ldquo;in other words&rdquo; illogically signals that the sentence that follows is a restatement of the information in the previous sentence; instead, the sentence that follows provides additional information that is true in spite of the preceding information. Choice D is incorrect because &ldquo;as a result&rdquo; illogically signals that the sentence that follows is a result of the information in the previous sentence regarding the correlation between iconicity and acquisition; instead, the sentence that follows is true in spite of the preceding information. </p>$SATQ$, false, 0, $SATQ$OSP-KA-TRA-H003$SATQ$, $SATQ$$SATQ$, $SATQ$b7a50e3d-5c8d-4ac9-80b7-277ccf0e1077$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"176edca6","external_id":"330ea545-cb02-4e1a-a12b-6bb6afc1c7fe","vaultid":"ee0f7049-9016-4d3f-a493-d41d97125d70","uId":"7a934e1c-1a72-42ac-831a-88675018ae20","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>A 2017 study of sign language learners tested the role of iconicity&mdash;the similarity of a sign to the thing it represents&mdash;in language acquisition. The study found that the<strong> </strong>greater the iconicity of a sign, the more likely it was to have been learned. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the correlation between acquisition and iconicity was lower than that between acquisition and another factor studied: sign frequency.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"17763e49-0cb0-46b4-9aaa-8e0a85d14c89","content":"<p>In fact,</p>"},{"id":"393d4b8a-31b7-4cb6-a685-69373420cfbb","content":"<p>In other words,</p>"},{"id":"83c1b541-9190-4fda-9185-83502ad9fb9f","content":"<p>Granted,</p>"},{"id":"16463f5d-0df2-4ddb-91e1-a1aefcc9f938","content":"<p>As a result,</p>"}],"keys":["83c1b541-9190-4fda-9185-83502ad9fb9f"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. &ldquo;Granted&rdquo; logically signals that the following information&mdash;that iconicity is not as highly correlated with acquisition as sign frequency&mdash;is true in spite of the information about the correlation between iconicity and acquisition in the previous sentence. </p><p>Choice A is incorrect because &ldquo;in fact&rdquo; illogically signals that the sentence that follows either emphasizes or refutes the information in the previous sentence regarding the correlation between iconicity and acquisition. Instead, the sentence that follows provides additional information that is true in spite of the preceding information; it neither emphasizes nor refutes that information. Choice B is incorrect because &ldquo;in other words&rdquo; illogically signals that the sentence that follows is a restatement of the information in the previous sentence; instead, the sentence that follows provides additional information that is true in spite of the preceding information. Choice D is incorrect because &ldquo;as a result&rdquo; illogically signals that the sentence that follows is a result of the information in the previous sentence regarding the correlation between iconicity and acquisition; instead, the sentence that follows is true in spite of the preceding information. </p>","parenttemplatename":"OSP-KA-TRA-H003","parenttemplateid":"","templateclusterid":"b7a50e3d-5c8d-4ac9-80b7-277ccf0e1077","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959373,"updateDate":1691007959373}$SATQ$::jsonb, 1691007959373, 1691007959373),
    ($SATQ$1773fa73$SATQ$, $SATQ$6b2053d2-4dcb-49c5-a3a1-70df096d9d56$SATQ$::uuid, $SATQ$4019870b-be9d-42ca-8827-5be6becb282d$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>A commodity chain is the series of links connecting the production and purchase of a commodity on the world market.</li>
<li>Chinese American anthropologist Anna Tsing studies the contemporary commodity chain of matsutake mushrooms.</li>
<li>At one end of the matsutake chain are mushroom pickers in Oregon.</li>
<li>At the other end are wealthy consumers who buy the costly matsutake in Japan.</li>
<li>According to Tsing, &ldquo;Japanese traders began importing matsutake in the 1980s, when the scarcity of matsutake in Japan first became clear.&rdquo;</li>
</ul>$SATQ$, $SATQ$<p>The student wants to provide an overview of the matsutake commodity chain. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"5f031dad-4602-4f0c-adef-8d10f70cff3e","content":"<p>The contemporary matsutake commodity chain has its origins in the 1980s when, according to Tsing, &ldquo;the scarcity of matsutake in Japan first became clear.&rdquo;</p>"},{"id":"0687e689-75b8-4221-b350-b7ae403e4a17","content":"<p>Commodity chains include the linked production and purchase of commodities, such as the matsutake mushroom, on the world market.</p>"},{"id":"de9c93d0-2c2e-4e25-a8a0-0ae07e482138","content":"<p>Decades after the Japanese import of matsutake began, a commodity chain now links matsutake pickers in Oregon with wealthy consumers of the costly mushrooms in Japan.</p>"},{"id":"7fef10e7-800d-4308-a5a3-351594a271a5","content":"<p>Wealthy consumers who buy the costly mushrooms in Japan are at one end of the matsutake commodity chain.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["de9c93d0-2c2e-4e25-a8a0-0ae07e482138"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The sentence provides an overview of the matsutake commodity chain, connecting the Oregon mushroom pickers at one end to the Japanese consumers at the other. </p><p>Choice A is incorrect. While the sentence mentions the matsutake commodity chain, it focuses only on its origins; it does not provide an overview. Choice B is incorrect. The sentence provides a general definition of commodity chains, not an overview of the matsutake chain. Choice D is incorrect. While the sentence mentions the matsutake commodity chain, it focuses only on one end of the chain (the consumers); it does not provide an overview. </p>$SATQ$, false, 0, $SATQ$OSP-032-SYN$SATQ$, $SATQ$$SATQ$, $SATQ$9b790a1c-fb3b-4229-aa84-3a8be15f2eeb$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"1773fa73","external_id":"6b2053d2-4dcb-49c5-a3a1-70df096d9d56","vaultid":"4019870b-be9d-42ca-8827-5be6becb282d","uId":"7ff93096-45f6-40e0-8044-f08725c33d94","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>A commodity chain is the series of links connecting the production and purchase of a commodity on the world market.</li>\n<li>Chinese American anthropologist Anna Tsing studies the contemporary commodity chain of matsutake mushrooms.</li>\n<li>At one end of the matsutake chain are mushroom pickers in Oregon.</li>\n<li>At the other end are wealthy consumers who buy the costly matsutake in Japan.</li>\n<li>According to Tsing, &ldquo;Japanese traders began importing matsutake in the 1980s, when the scarcity of matsutake in Japan first became clear.&rdquo;</li>\n</ul>","stem":"<p>The student wants to provide an overview of the matsutake commodity chain. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"5f031dad-4602-4f0c-adef-8d10f70cff3e","content":"<p>The contemporary matsutake commodity chain has its origins in the 1980s when, according to Tsing, &ldquo;the scarcity of matsutake in Japan first became clear.&rdquo;</p>"},{"id":"0687e689-75b8-4221-b350-b7ae403e4a17","content":"<p>Commodity chains include the linked production and purchase of commodities, such as the matsutake mushroom, on the world market.</p>"},{"id":"de9c93d0-2c2e-4e25-a8a0-0ae07e482138","content":"<p>Decades after the Japanese import of matsutake began, a commodity chain now links matsutake pickers in Oregon with wealthy consumers of the costly mushrooms in Japan.</p>"},{"id":"7fef10e7-800d-4308-a5a3-351594a271a5","content":"<p>Wealthy consumers who buy the costly mushrooms in Japan are at one end of the matsutake commodity chain.</p>"}],"keys":["de9c93d0-2c2e-4e25-a8a0-0ae07e482138"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The sentence provides an overview of the matsutake commodity chain, connecting the Oregon mushroom pickers at one end to the Japanese consumers at the other. </p><p>Choice A is incorrect. While the sentence mentions the matsutake commodity chain, it focuses only on its origins; it does not provide an overview. Choice B is incorrect. The sentence provides a general definition of commodity chains, not an overview of the matsutake chain. Choice D is incorrect. While the sentence mentions the matsutake commodity chain, it focuses only on one end of the chain (the consumers); it does not provide an overview. </p>","parenttemplatename":"OSP-032-SYN","parenttemplateid":"","templateclusterid":"9b790a1c-fb3b-4229-aa84-3a8be15f2eeb","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959319,"updateDate":1691007959319}$SATQ$::jsonb, 1691007959319, 1691007959319),
    ($SATQ$1792fa73$SATQ$, $SATQ$26395958-deab-4ad0-bd1c-e96ac82d8ebc$SATQ$::uuid, $SATQ$8c03639a-29ef-4821-b45e-c24b6b4ad975$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>The tundra is a type of environment characterized by especially harsh winter conditions.</li>
<li>Winter temperatures in the tundra average a frigid <span aria-hidden="true">&minus;30</span><span class="sr-only">negative 30</span> degrees Fahrenheit.</li>
<li>Animals that have adapted to these conditions can survive tundra winters.</li>
<li>During the tundra&rsquo;s short growing season, average temperatures can reach a relatively mild 54 degrees Fahrenheit.</li>
<li>Around 1,700 different kinds of plants are able to grow in the tundra.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to emphasize how harsh the conditions can be in the tundra. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"66839af1-368e-4040-83aa-68cb6a2ec8e5","content":"<p>Winters in the tundra are especially harsh, with temperatures averaging a frigid <span aria-hidden=\"true\">&minus;30</span><span class=\"sr-only\">negative 30</span> degrees Fahrenheit.</p>"},{"id":"00149f58-1672-441d-8c31-3e6aa6cc48e2","content":"<p>Animals that have adapted to harsh winter conditions can survive tundra winters.</p>"},{"id":"954f8735-6d78-4f4b-8430-10d95e1c87b9","content":"<p>There are around 1,700 different kinds of plants that can live in the tundra, where average temperatures can reach a mild 54 degrees Fahrenheit.</p>"},{"id":"9f6d5116-14f4-480b-bce2-5242a311ac53","content":"<p>Along with animals that have adapted to the tundra&rsquo;s conditions, around 1,700 different kinds of plants can live in the tundra.</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["66839af1-368e-4040-83aa-68cb6a2ec8e5"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The sentence emphasizes how harsh the conditions in the tundra can be, noting that the winters are especially harsh and describing the average temperatures as &ldquo;frigid.&rdquo; </p><p>Choice B is incorrect because the sentence explains that some animals can survive harsh tundra winters; it doesn&rsquo;t emphasize how harsh the conditions can be. Choice C is incorrect because the sentence specifies how many different kinds of plants can live in the tundra; it doesn&rsquo;t emphasize how harsh the conditions in the tundra can be. Choice D is incorrect because the sentence explains that both plants and animals can survive in the tundra; it doesn&rsquo;t emphasize how harsh the conditions in the tundra can be. </p>$SATQ$, false, 0, $SATQ$OSP-009-SYN$SATQ$, $SATQ$$SATQ$, $SATQ$93c0ae1f-b293-4ba3-8fc3-3f972b6ad6a6$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"1792fa73","external_id":"26395958-deab-4ad0-bd1c-e96ac82d8ebc","vaultid":"8c03639a-29ef-4821-b45e-c24b6b4ad975","uId":"62e57ec9-001e-416d-aef4-5152816e5c80","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>The tundra is a type of environment characterized by especially harsh winter conditions.</li>\n<li>Winter temperatures in the tundra average a frigid <span aria-hidden=\"true\">&minus;30</span><span class=\"sr-only\">negative 30</span> degrees Fahrenheit.</li>\n<li>Animals that have adapted to these conditions can survive tundra winters.</li>\n<li>During the tundra&rsquo;s short growing season, average temperatures can reach a relatively mild 54 degrees Fahrenheit.</li>\n<li>Around 1,700 different kinds of plants are able to grow in the tundra.</li>\n</ul>","stem":"<p>The student wants to emphasize how harsh the conditions can be in the tundra. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"66839af1-368e-4040-83aa-68cb6a2ec8e5","content":"<p>Winters in the tundra are especially harsh, with temperatures averaging a frigid <span aria-hidden=\"true\">&minus;30</span><span class=\"sr-only\">negative 30</span> degrees Fahrenheit.</p>"},{"id":"00149f58-1672-441d-8c31-3e6aa6cc48e2","content":"<p>Animals that have adapted to harsh winter conditions can survive tundra winters.</p>"},{"id":"954f8735-6d78-4f4b-8430-10d95e1c87b9","content":"<p>There are around 1,700 different kinds of plants that can live in the tundra, where average temperatures can reach a mild 54 degrees Fahrenheit.</p>"},{"id":"9f6d5116-14f4-480b-bce2-5242a311ac53","content":"<p>Along with animals that have adapted to the tundra&rsquo;s conditions, around 1,700 different kinds of plants can live in the tundra.</p>"}],"keys":["66839af1-368e-4040-83aa-68cb6a2ec8e5"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The sentence emphasizes how harsh the conditions in the tundra can be, noting that the winters are especially harsh and describing the average temperatures as &ldquo;frigid.&rdquo; </p><p>Choice B is incorrect because the sentence explains that some animals can survive harsh tundra winters; it doesn&rsquo;t emphasize how harsh the conditions can be. Choice C is incorrect because the sentence specifies how many different kinds of plants can live in the tundra; it doesn&rsquo;t emphasize how harsh the conditions in the tundra can be. Choice D is incorrect because the sentence explains that both plants and animals can survive in the tundra; it doesn&rsquo;t emphasize how harsh the conditions in the tundra can be. </p>","parenttemplatename":"OSP-009-SYN","parenttemplateid":"","templateclusterid":"93c0ae1f-b293-4ba3-8fc3-3f972b6ad6a6","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959314,"updateDate":1691007959314}$SATQ$::jsonb, 1691007959314, 1691007959314),
    ($SATQ$17e49403$SATQ$, $SATQ$062b539c-799e-4ad4-921c-a3be44fcf2e8$SATQ$::uuid, $SATQ$57cd2088-b301-4b20-b05c-8a815110ebee$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 5, $SATQ$mcq$SATQ$, $SATQ$<p>When, in the 1800s, geologists first realized that much of Earth had once been covered by great sheets of ice, some theorized that the phenomenon was cyclical, occurring at regular intervals. Each Ice Age is so destructive, though, that it largely erases the geological evidence of its predecessor. <span aria-hidden="true">______</span><span class="sr-only">blank</span> geologists were unable to confirm the theory of cyclical Ice Ages until the 1960s.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"000c4e7a-150a-48c7-8036-f16a10cd9717","content":"<p>Hence,</p>"},{"id":"36bd09b8-558e-4ae5-a7fd-b8b2db3d1187","content":"<p>Moreover,</p>"},{"id":"e7527fe7-9769-4d76-8415-6771eebfe938","content":"<p>Nevertheless,</p>"},{"id":"8d16bb99-dd30-4531-baa3-ce8c12dc90f2","content":"<p>Next,</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["000c4e7a-150a-48c7-8036-f16a10cd9717"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. &ldquo;Hence&rdquo; logically signals that the information in this sentence&mdash;that geologists couldn&rsquo;t confirm the theory of cyclical Ice Ages until the 1960s&mdash;is a consequence of the previous information about the destructiveness of each Ice Age and the erasure of necessary geological evidence. &nbsp;</p><p>Choice B is incorrect because &ldquo;moreover&rdquo; illogically signals that the information in this sentence is merely additional to the previous information about the destructiveness of each Ice Age. Instead, the sentence&nbsp; identifies a specific consequence of that information. Choice C is incorrect because &ldquo;nevertheless&rdquo; illogically signals that the information in this sentence is true despite the previous information about the destructiveness of each Ice Age. Instead, the sentence identifies a specific consequence of that information. Choice D is incorrect because &ldquo;next&rdquo; illogically signals that the information in this sentence is the next step in a process. Instead, the sentence identifies a specific consequence of the previous information. </p>$SATQ$, false, 0, $SATQ$OSP-234-TRA$SATQ$, $SATQ$$SATQ$, $SATQ$610888a0-7916-4a6d-b35e-fae804ef5687$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"17e49403","external_id":"062b539c-799e-4ad4-921c-a3be44fcf2e8","vaultid":"57cd2088-b301-4b20-b05c-8a815110ebee","uId":"8d85d0bd-598c-4715-8e26-248331588266","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":5,"type":"mcq","stimulus":"<p>When, in the 1800s, geologists first realized that much of Earth had once been covered by great sheets of ice, some theorized that the phenomenon was cyclical, occurring at regular intervals. Each Ice Age is so destructive, though, that it largely erases the geological evidence of its predecessor. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> geologists were unable to confirm the theory of cyclical Ice Ages until the 1960s.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"000c4e7a-150a-48c7-8036-f16a10cd9717","content":"<p>Hence,</p>"},{"id":"36bd09b8-558e-4ae5-a7fd-b8b2db3d1187","content":"<p>Moreover,</p>"},{"id":"e7527fe7-9769-4d76-8415-6771eebfe938","content":"<p>Nevertheless,</p>"},{"id":"8d16bb99-dd30-4531-baa3-ce8c12dc90f2","content":"<p>Next,</p>"}],"keys":["000c4e7a-150a-48c7-8036-f16a10cd9717"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. &ldquo;Hence&rdquo; logically signals that the information in this sentence&mdash;that geologists couldn&rsquo;t confirm the theory of cyclical Ice Ages until the 1960s&mdash;is a consequence of the previous information about the destructiveness of each Ice Age and the erasure of necessary geological evidence. &nbsp;</p><p>Choice B is incorrect because &ldquo;moreover&rdquo; illogically signals that the information in this sentence is merely additional to the previous information about the destructiveness of each Ice Age. Instead, the sentence&nbsp; identifies a specific consequence of that information. Choice C is incorrect because &ldquo;nevertheless&rdquo; illogically signals that the information in this sentence is true despite the previous information about the destructiveness of each Ice Age. Instead, the sentence identifies a specific consequence of that information. Choice D is incorrect because &ldquo;next&rdquo; illogically signals that the information in this sentence is the next step in a process. Instead, the sentence identifies a specific consequence of the previous information. </p>","parenttemplatename":"OSP-234-TRA","parenttemplateid":"","templateclusterid":"610888a0-7916-4a6d-b35e-fae804ef5687","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959333,"updateDate":1691007959333}$SATQ$::jsonb, 1691007959333, 1691007959333),
    ($SATQ$17ec916d$SATQ$, $SATQ$67fd9114-ebd9-44c4-9e4b-c1476f3ac68a$SATQ$::uuid, $SATQ$7f747076-4952-43b5-ad96-80c4e9cf4404$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p> While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Bharati Mukherjee was an Indian-born author of novels and short stories.</li>
<li>She published the novel <em>The Holder of the World</em> in 1993.</li>
<li>A central character in the novel is a woman living in twentieth-century United States.</li>
<li>Another central character is a woman living in seventeenth-century India.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to introduce the novel <em>The Holder of the World </em>to an audience already familiar with Bharati Mukherjee. Which choice most effectively uses relevant information from the notes to accomplish this goal?&nbsp;</p>$SATQ$, $SATQ$[{"id":"8cf7736a-b033-4c05-abeb-bf26dd630391","content":"<p>Bharati Mukherjee&rsquo;s settings include both twentieth-century United States and seventeenth-century India.</p>"},{"id":"6acefbdf-d339-41c8-8222-9c697782f3ee","content":"<p>In addition to her novel <em>The Holder of the World, </em>which was published in 1993, Indian-born author Bharati Mukherjee wrote other novels and short stories.</p>"},{"id":"8d9223b8-0288-4e9b-8fc8-1e552d3e9ec0","content":"<p>Bharati Mukherjee&rsquo;s novel <em>The Holder of the World </em>centers around two women, one living in twentieth-century United States and the other in seventeenth-century India.</p>"},{"id":"56345278-0fe0-470c-8fbc-d13a76c6c0fb","content":"<p><em>The Holder of the World </em>was not the only novel written by Indian-born author Bharati Mukherjee.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["8d9223b8-0288-4e9b-8fc8-1e552d3e9ec0"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. The sentence effectively introduces <em>The Holder of the World</em> to an audience already familiar with Mukherjee, explaining that the novel centers around two women and mentioning the author without providing any other identifying information. </p><p>Choice A is incorrect. The sentence provides a detail about Mukherjee&rsquo;s settings; it doesn&rsquo;t introduce, or even mention, the novel. Choice B is incorrect. The sentence provides introductory information about Mukherjee; it doesn&rsquo;t effectively introduce her novel to an audience already familiar with the author. Choice D is incorrect. The sentence provides introductory information about Mukherjee; it doesn&rsquo;t effectively introduce her novel to an audience already familiar with the author. </p>$SATQ$, false, 0, $SATQ$OSP-734-SYN$SATQ$, $SATQ$$SATQ$, $SATQ$3dd14bd7-fe18-4eb4-a669-e46795c04c0d$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"17ec916d","external_id":"67fd9114-ebd9-44c4-9e4b-c1476f3ac68a","vaultid":"7f747076-4952-43b5-ad96-80c4e9cf4404","uId":"68524fd1-a0ba-440c-a8b8-23ff03376824","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p> While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Bharati Mukherjee was an Indian-born author of novels and short stories.</li>\n<li>She published the novel <em>The Holder of the World</em> in 1993.</li>\n<li>A central character in the novel is a woman living in twentieth-century United States.</li>\n<li>Another central character is a woman living in seventeenth-century India.</li>\n</ul>","stem":"<p>The student wants to introduce the novel <em>The Holder of the World </em>to an audience already familiar with Bharati Mukherjee. Which choice most effectively uses relevant information from the notes to accomplish this goal?&nbsp;</p>","answerOptions":[{"id":"8cf7736a-b033-4c05-abeb-bf26dd630391","content":"<p>Bharati Mukherjee&rsquo;s settings include both twentieth-century United States and seventeenth-century India.</p>"},{"id":"6acefbdf-d339-41c8-8222-9c697782f3ee","content":"<p>In addition to her novel <em>The Holder of the World, </em>which was published in 1993, Indian-born author Bharati Mukherjee wrote other novels and short stories.</p>"},{"id":"8d9223b8-0288-4e9b-8fc8-1e552d3e9ec0","content":"<p>Bharati Mukherjee&rsquo;s novel <em>The Holder of the World </em>centers around two women, one living in twentieth-century United States and the other in seventeenth-century India.</p>"},{"id":"56345278-0fe0-470c-8fbc-d13a76c6c0fb","content":"<p><em>The Holder of the World </em>was not the only novel written by Indian-born author Bharati Mukherjee.</p>"}],"keys":["8d9223b8-0288-4e9b-8fc8-1e552d3e9ec0"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. The sentence effectively introduces <em>The Holder of the World</em> to an audience already familiar with Mukherjee, explaining that the novel centers around two women and mentioning the author without providing any other identifying information. </p><p>Choice A is incorrect. The sentence provides a detail about Mukherjee&rsquo;s settings; it doesn&rsquo;t introduce, or even mention, the novel. Choice B is incorrect. The sentence provides introductory information about Mukherjee; it doesn&rsquo;t effectively introduce her novel to an audience already familiar with the author. Choice D is incorrect. The sentence provides introductory information about Mukherjee; it doesn&rsquo;t effectively introduce her novel to an audience already familiar with the author. </p>","parenttemplatename":"OSP-734-SYN","parenttemplateid":"","templateclusterid":"3dd14bd7-fe18-4eb4-a669-e46795c04c0d","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959349,"updateDate":1691007959349}$SATQ$::jsonb, 1691007959349, 1691007959349),
    ($SATQ$1872cd6d$SATQ$, $SATQ$5c88c6f7-538c-495b-b746-e9ba2be11495$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>When printing paper money for the colony of Pennsylvania in the 1730s, Benjamin Franklin&mdash;then a Philadelphia shop owner&mdash;took steps to combat the circulation of counterfeit notes, such as weaving blue threads and muscovite (a reflective mineral) into the paper he used. <span aria-hidden="true">______</span><span class="sr-only">blank</span> he stamped the notes with detailed imprints of sage leaves that proved difficult for forgers to replicate.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"85c9351c-a7f1-4990-be15-c7d9deedc928","content":"<p>Specifically,</p>"},{"id":"5b5cf0de-c459-45d5-beac-18e9fa5ac774","content":"<p>That said,</p>"},{"id":"42c51bec-d835-41e5-954c-3b18d18f1f1d","content":"<p>For example,&nbsp;</p>"},{"id":"5adc6b6e-6b2e-47d0-bccb-fc6a0b950cf3","content":"<p>Moreover,</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["5adc6b6e-6b2e-47d0-bccb-fc6a0b950cf3"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. "Moreover" logically signals that the information in this sentence&mdash;that Franklin stamped imprints on paper money to make forgery more difficult&mdash;adds to the previous information by describing Franklin&rsquo;s other strategy for combatting forgers: weaving materials into the paper used for printing money.</p><p>Choice A is incorrect because "specifically" illogically signals that the information in this sentence provides specific, precise details elaborating on the previous information about Franklin&rsquo;s other strategy for combatting forgers (weaving materials into paper). Instead, this information about stamping imprints on money adds new information. Choice B is incorrect because "that said" illogically signals that the information in this sentence is an exception to the previous information about Franklin&rsquo;s other strategy for combatting forgers (weaving materials into paper). Instead, this information about stamping imprints on money adds new information. Choice C is incorrect because "for example" illogically signals that the information in this sentence serves as an example of the previous information about Franklin&rsquo;s other strategy for combatting forgers (weaving materials into paper). Instead, this information about stamping imprints on money adds new information.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"1872cd6d","external_id":"5c88c6f7-538c-495b-b746-e9ba2be11495","vaultid":null,"uId":"a6741f9a-d9d0-4c50-9260-c89b3ce5024c","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>When printing paper money for the colony of Pennsylvania in the 1730s, Benjamin Franklin&mdash;then a Philadelphia shop owner&mdash;took steps to combat the circulation of counterfeit notes, such as weaving blue threads and muscovite (a reflective mineral) into the paper he used. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> he stamped the notes with detailed imprints of sage leaves that proved difficult for forgers to replicate.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"85c9351c-a7f1-4990-be15-c7d9deedc928","content":"<p>Specifically,</p>"},{"id":"5b5cf0de-c459-45d5-beac-18e9fa5ac774","content":"<p>That said,</p>"},{"id":"42c51bec-d835-41e5-954c-3b18d18f1f1d","content":"<p>For example,&nbsp;</p>"},{"id":"5adc6b6e-6b2e-47d0-bccb-fc6a0b950cf3","content":"<p>Moreover,</p>"}],"keys":["5adc6b6e-6b2e-47d0-bccb-fc6a0b950cf3"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. \"Moreover\" logically signals that the information in this sentence&mdash;that Franklin stamped imprints on paper money to make forgery more difficult&mdash;adds to the previous information by describing Franklin&rsquo;s other strategy for combatting forgers: weaving materials into the paper used for printing money.</p><p>Choice A is incorrect because \"specifically\" illogically signals that the information in this sentence provides specific, precise details elaborating on the previous information about Franklin&rsquo;s other strategy for combatting forgers (weaving materials into paper). Instead, this information about stamping imprints on money adds new information. Choice B is incorrect because \"that said\" illogically signals that the information in this sentence is an exception to the previous information about Franklin&rsquo;s other strategy for combatting forgers (weaving materials into paper). Instead, this information about stamping imprints on money adds new information. Choice C is incorrect because \"for example\" illogically signals that the information in this sentence serves as an example of the previous information about Franklin&rsquo;s other strategy for combatting forgers (weaving materials into paper). Instead, this information about stamping imprints on money adds new information.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669207,"updateDate":1743430669207}$SATQ$::jsonb, 1743430669207, 1743430669207),
    ($SATQ$1996c104$SATQ$, $SATQ$29bc77ca-7030-419b-953a-56db063b4d1e$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>The liquid metals in Earth&rsquo;s core circulate constantly, and this circulation generates electrical currents that flow between Earth&rsquo;s North and South magnetic poles. These electrical currents, <span aria-hidden="true">______</span><span class="sr-only">blank</span> create a barrier around Earth that protects us from radiation and charged particles coming from space.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"a687d31c-8762-4a39-87d9-b0f208e0c765","content":"<p>in turn,</p>"},{"id":"493ca8ac-8921-43b2-9dc3-9a15230ee300","content":"<p>likewise,</p>"},{"id":"f121c622-8193-4303-a450-09c6ec621ce4","content":"<p>nevertheless,</p>"},{"id":"df39e045-04a8-43f0-97fd-4f65d0d60249","content":"<p>in reality,</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["a687d31c-8762-4a39-87d9-b0f208e0c765"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. "In turn" logically signals that the information in the sentence&mdash;that the electrical currents create a protective barrier around Earth&mdash;is a result or consequence of the previous information about the circulation of liquid metals generating electrical currents that flow between Earth&rsquo;s magnetic poles.</p><p>Choice B is incorrect because "likewise" illogically signals that the information in the sentence is similar to the previous information about the circulation of liquid metals generating electrical currents that flow between Earth&rsquo;s magnetic poles. Instead, the new information about the electrical currents is a direct result or consequence of the previous information. Choice C is incorrect because "nevertheless" illogically signals that the information in the sentence is true despite the previous information about the circulation of liquid metals generating electrical currents that flow between Earth&rsquo;s magnetic poles. Instead, the new information about the electrical currents is a direct result or consequence of the previous information. Choice D is incorrect because "in reality" illogically signals that the information in the sentence contradicts the previous information about the circulation of liquid metals generating electrical currents that flow between Earth&rsquo;s magnetic poles. Instead, the new information about the electrical currents is a direct result or consequence of the previous information.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"1996c104","external_id":"29bc77ca-7030-419b-953a-56db063b4d1e","vaultid":null,"uId":"db7c6323-d29a-4bb3-93e1-b5b68f724a56","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>The liquid metals in Earth&rsquo;s core circulate constantly, and this circulation generates electrical currents that flow between Earth&rsquo;s North and South magnetic poles. These electrical currents, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> create a barrier around Earth that protects us from radiation and charged particles coming from space.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"a687d31c-8762-4a39-87d9-b0f208e0c765","content":"<p>in turn,</p>"},{"id":"493ca8ac-8921-43b2-9dc3-9a15230ee300","content":"<p>likewise,</p>"},{"id":"f121c622-8193-4303-a450-09c6ec621ce4","content":"<p>nevertheless,</p>"},{"id":"df39e045-04a8-43f0-97fd-4f65d0d60249","content":"<p>in reality,</p>"}],"keys":["a687d31c-8762-4a39-87d9-b0f208e0c765"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. \"In turn\" logically signals that the information in the sentence&mdash;that the electrical currents create a protective barrier around Earth&mdash;is a result or consequence of the previous information about the circulation of liquid metals generating electrical currents that flow between Earth&rsquo;s magnetic poles.</p><p>Choice B is incorrect because \"likewise\" illogically signals that the information in the sentence is similar to the previous information about the circulation of liquid metals generating electrical currents that flow between Earth&rsquo;s magnetic poles. Instead, the new information about the electrical currents is a direct result or consequence of the previous information. Choice C is incorrect because \"nevertheless\" illogically signals that the information in the sentence is true despite the previous information about the circulation of liquid metals generating electrical currents that flow between Earth&rsquo;s magnetic poles. Instead, the new information about the electrical currents is a direct result or consequence of the previous information. Choice D is incorrect because \"in reality\" illogically signals that the information in the sentence contradicts the previous information about the circulation of liquid metals generating electrical currents that flow between Earth&rsquo;s magnetic poles. Instead, the new information about the electrical currents is a direct result or consequence of the previous information.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323042,"updateDate":1730147323042}$SATQ$::jsonb, 1730147323042, 1730147323042),
    ($SATQ$1a8126aa$SATQ$, $SATQ$643d6efb-497b-497b-a36c-4c6d2b2baa05$SATQ$::uuid, $SATQ$5c6ed375-32ba-49b9-9ea2-3301f59371fb$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>In 2019, researcher Patricia Jurado Gonzalez and food historian Nawal Nasrallah prepared a stew from a 4,000-year-old recipe found on a Mesopotamian clay tablet. When they tasted the dish, known as <em>pa&scaron;rūtum </em>(&ldquo;unwinding&rdquo;), they found that it had a mild taste and inspired a sense of calm. <span aria-hidden="true">______</span><span class="sr-only">blank</span> the researchers, knowing that dishes were sometimes named after their intended effects, theorized that the dish&rsquo;s name, &ldquo;unwinding,&rdquo; referred to its function: to help ancient diners relax.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"7b193331-e950-44dd-a8e7-8f934c8eaa27","content":"<p>Therefore,</p>"},{"id":"f424a0b1-8fbf-4de2-8ee2-cac83afb45f5","content":"<p>Alternately,</p>"},{"id":"42e555a3-e19e-4562-ae5b-4b89f68454b3","content":"<p>Nevertheless,</p>"},{"id":"2ab7f5f1-3bce-4865-a896-5dc1107da02d","content":"<p>Likewise,</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["7b193331-e950-44dd-a8e7-8f934c8eaa27"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. "Therefore" logically signals that the action described in this sentence&mdash;the researchers theorizing that the dish was named for its effect on diners&mdash;is a result or consequence of the previous observation that the dish had a calming effect.</p><p>Choice B is incorrect because "alternately" illogically signals that the action described in this sentence offers an alternative or contrast to the previous observation that the dish had a calming effect. Instead, the action is a result or consequence of that observation. Choice C is incorrect because "nevertheless" illogically signals that the action described in this sentence occurs despite the previous observation that the dish had a calming effect. Instead, the action is a result or consequence of that observation. Choice D is incorrect because "likewise" illogically signals that this sentence merely adds a second, similar detail to the previous observation that the dish had a calming effect. Instead, this sentence describes an action that is a result or consequence of that observation.</p>$SATQ$, false, 0, $SATQ$OSP-201-TRA$SATQ$, $SATQ$$SATQ$, $SATQ$a256a63b-bbad-4487-97e6-ce53d834e288$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"1a8126aa","external_id":"643d6efb-497b-497b-a36c-4c6d2b2baa05","vaultid":"5c6ed375-32ba-49b9-9ea2-3301f59371fb","uId":"32adc5a3-db5d-42f3-b7c7-3d08229db116","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>In 2019, researcher Patricia Jurado Gonzalez and food historian Nawal Nasrallah prepared a stew from a 4,000-year-old recipe found on a Mesopotamian clay tablet. When they tasted the dish, known as <em>pa&scaron;rūtum </em>(&ldquo;unwinding&rdquo;), they found that it had a mild taste and inspired a sense of calm. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> the researchers, knowing that dishes were sometimes named after their intended effects, theorized that the dish&rsquo;s name, &ldquo;unwinding,&rdquo; referred to its function: to help ancient diners relax.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"7b193331-e950-44dd-a8e7-8f934c8eaa27","content":"<p>Therefore,</p>"},{"id":"f424a0b1-8fbf-4de2-8ee2-cac83afb45f5","content":"<p>Alternately,</p>"},{"id":"42e555a3-e19e-4562-ae5b-4b89f68454b3","content":"<p>Nevertheless,</p>"},{"id":"2ab7f5f1-3bce-4865-a896-5dc1107da02d","content":"<p>Likewise,</p>"}],"keys":["7b193331-e950-44dd-a8e7-8f934c8eaa27"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. \"Therefore\" logically signals that the action described in this sentence&mdash;the researchers theorizing that the dish was named for its effect on diners&mdash;is a result or consequence of the previous observation that the dish had a calming effect.</p><p>Choice B is incorrect because \"alternately\" illogically signals that the action described in this sentence offers an alternative or contrast to the previous observation that the dish had a calming effect. Instead, the action is a result or consequence of that observation. Choice C is incorrect because \"nevertheless\" illogically signals that the action described in this sentence occurs despite the previous observation that the dish had a calming effect. Instead, the action is a result or consequence of that observation. Choice D is incorrect because \"likewise\" illogically signals that this sentence merely adds a second, similar detail to the previous observation that the dish had a calming effect. Instead, this sentence describes an action that is a result or consequence of that observation.</p>","parenttemplatename":"OSP-201-TRA","parenttemplateid":"","templateclusterid":"a256a63b-bbad-4487-97e6-ce53d834e288","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959325,"updateDate":1691007959325}$SATQ$::jsonb, 1691007959325, 1691007959325),
    ($SATQ$1b219d14$SATQ$, $SATQ$f6891dfb-dd59-4b44-90e4-b75a1765bdf4$SATQ$::uuid, $SATQ$199b3b26-77c2-4c54-87f0-9023cb74cc6c$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 3, $SATQ$mcq$SATQ$, $SATQ$<p>As a young historian in the 1950s, Alixa Naff began interviewing fellow Arab American immigrants about their experiences straddling two cultures. Over the next few decades, Naff conducted more than 450 such interviews, also known as oral histories. <span aria-hidden="true">______</span><span class="sr-only">blank</span> she collected photographs and other artifacts that represented her subjects&rsquo; experiences.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"63e78bc3-3755-4ab9-bc77-556ad65f28a6","content":"<p>In other words,</p>"},{"id":"5d454f81-c580-48ca-8029-b0f2161a72b8","content":"<p>On the contrary,</p>"},{"id":"04e20dbc-4b68-4638-a3a1-c7542ac9f60b","content":"<p>In addition,</p>"},{"id":"aee91192-3caa-46fb-a2ce-ae9f29eca635","content":"<p>Today,</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["04e20dbc-4b68-4638-a3a1-c7542ac9f60b"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. "In addition" logically signals that Naff&rsquo;s artifact collecting was separate from, and in addition to, her interviewing.</p><p>Choice A is incorrect because "in other words" illogically signals that the information about Naff&rsquo;s artifact collecting restates the previous information about her interviewing. Instead, Naff collected artifacts in addition to conducting interviews. Choice B is incorrect because "on the contrary" illogically signals that Naff&rsquo;s artifact collecting was contrary to her interviewing. Instead, Naff collected artifacts in addition to conducting interviews. Choice D is incorrect because "today" illogically signals that Naff&rsquo;s artifact collecting is occurring in the present day. Instead, this activity occurred in the past, as indicated by the past tense verb "collected."</p>$SATQ$, false, 0, $SATQ$OSP-247-TRA$SATQ$, $SATQ$$SATQ$, $SATQ$029f4f9d-bb2d-48bb-a766-765194a2e8bb$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"1b219d14","external_id":"f6891dfb-dd59-4b44-90e4-b75a1765bdf4","vaultid":"199b3b26-77c2-4c54-87f0-9023cb74cc6c","uId":"2fd0ca76-5cb4-41e9-8b16-6b3734419b90","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":3,"type":"mcq","stimulus":"<p>As a young historian in the 1950s, Alixa Naff began interviewing fellow Arab American immigrants about their experiences straddling two cultures. Over the next few decades, Naff conducted more than 450 such interviews, also known as oral histories. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> she collected photographs and other artifacts that represented her subjects&rsquo; experiences.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"63e78bc3-3755-4ab9-bc77-556ad65f28a6","content":"<p>In other words,</p>"},{"id":"5d454f81-c580-48ca-8029-b0f2161a72b8","content":"<p>On the contrary,</p>"},{"id":"04e20dbc-4b68-4638-a3a1-c7542ac9f60b","content":"<p>In addition,</p>"},{"id":"aee91192-3caa-46fb-a2ce-ae9f29eca635","content":"<p>Today,</p>"}],"keys":["04e20dbc-4b68-4638-a3a1-c7542ac9f60b"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. \"In addition\" logically signals that Naff&rsquo;s artifact collecting was separate from, and in addition to, her interviewing.</p><p>Choice A is incorrect because \"in other words\" illogically signals that the information about Naff&rsquo;s artifact collecting restates the previous information about her interviewing. Instead, Naff collected artifacts in addition to conducting interviews. Choice B is incorrect because \"on the contrary\" illogically signals that Naff&rsquo;s artifact collecting was contrary to her interviewing. Instead, Naff collected artifacts in addition to conducting interviews. Choice D is incorrect because \"today\" illogically signals that Naff&rsquo;s artifact collecting is occurring in the present day. Instead, this activity occurred in the past, as indicated by the past tense verb \"collected.\"</p>","parenttemplatename":"OSP-247-TRA","parenttemplateid":"","templateclusterid":"029f4f9d-bb2d-48bb-a766-765194a2e8bb","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959333,"updateDate":1691007959333}$SATQ$::jsonb, 1691007959333, 1691007959333),
    ($SATQ$1b94a80a$SATQ$, $SATQ$47d66dea-12b0-4883-98b7-24518c0f4229$SATQ$::uuid, $SATQ$8a88e19a-f3bb-44cd-a9f0-c2b5149a73f3$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Wool is a natural&mdash;and economically important&mdash;fiber that is obtained from animals like sheep.</li>
<li>Australia is a leading producer of wool.</li>
<li>The thickness of wool fibers varies across sheep breeds.</li>
<li>Merino sheep produce fine wool that is used for apparel.</li>
<li>Rambouillet sheep produce fine wool that is used for apparel.</li>
<li>Romney sheep produce thick wool that is used for rugs and blankets.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to emphasize how Romney wool differs from Merino and Rambouillet wool. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"22a5f5fc-eb4c-4589-8a1e-9acf31b96fe2","content":"<p>Romney wool is just one of the many kinds of wools, each originating from a different breed of sheep.</p>"},{"id":"1471cbb5-cab9-41ce-a043-0da42607286e","content":"<p>Sheep wool varies from breed to breed, so Romney wool will be different than other kinds of wool.</p>"},{"id":"fa556045-31f9-4bc4-a1d5-fe60e313e85e","content":"<p>The fine wool produced by Merino and Rambouillet sheep is used for apparel, whereas the thicker wool of Romney sheep is used in rugs and blankets.</p>"},{"id":"77765d52-66c9-40e6-8764-bffae5431b43","content":"<p>Wool is an economically important fiber&mdash;especially in Australia&mdash;that can be used to make apparel or even rugs and blankets.</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["fa556045-31f9-4bc4-a1d5-fe60e313e85e"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. This choice most effectively emphasizes how Romney wool differs from Merino and Rambouillet wool. It describes the difference in thickness and the difference in what they&rsquo;re used for.&nbsp;</p><p>Choice A is incorrect. This choice doesn&rsquo;t emphasize how Romney wool differs from Merino and Rambouillet wool. It doesn&rsquo;t mention Merino or Rambouillet wool at all.&nbsp;Choice B is incorrect. This choice doesn&rsquo;t emphasize how Romney wool differs from Merino and Rambouillet wool. It doesn&rsquo;t mention Merino or Rambouillet wool at all.&nbsp;Choice D is incorrect. This choice doesn&rsquo;t emphasize how Romney wool differs from Merino and Rambouillet wool. It doesn&rsquo;t mention Romney, Merino or Rambouillet wool at all.&nbsp;</p>$SATQ$, false, 0, $SATQ$OSP-715-SYN$SATQ$, $SATQ$$SATQ$, $SATQ$de6e95a4-42f6-4b4a-99d8-5f2a5d43d0c1$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"1b94a80a","external_id":"47d66dea-12b0-4883-98b7-24518c0f4229","vaultid":"8a88e19a-f3bb-44cd-a9f0-c2b5149a73f3","uId":"746c95b6-98b2-4a75-adaf-7fd5fede45f9","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Wool is a natural&mdash;and economically important&mdash;fiber that is obtained from animals like sheep.</li>\n<li>Australia is a leading producer of wool.</li>\n<li>The thickness of wool fibers varies across sheep breeds.</li>\n<li>Merino sheep produce fine wool that is used for apparel.</li>\n<li>Rambouillet sheep produce fine wool that is used for apparel.</li>\n<li>Romney sheep produce thick wool that is used for rugs and blankets.</li>\n</ul>","stem":"<p>The student wants to emphasize how Romney wool differs from Merino and Rambouillet wool. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"22a5f5fc-eb4c-4589-8a1e-9acf31b96fe2","content":"<p>Romney wool is just one of the many kinds of wools, each originating from a different breed of sheep.</p>"},{"id":"1471cbb5-cab9-41ce-a043-0da42607286e","content":"<p>Sheep wool varies from breed to breed, so Romney wool will be different than other kinds of wool.</p>"},{"id":"fa556045-31f9-4bc4-a1d5-fe60e313e85e","content":"<p>The fine wool produced by Merino and Rambouillet sheep is used for apparel, whereas the thicker wool of Romney sheep is used in rugs and blankets.</p>"},{"id":"77765d52-66c9-40e6-8764-bffae5431b43","content":"<p>Wool is an economically important fiber&mdash;especially in Australia&mdash;that can be used to make apparel or even rugs and blankets.</p>"}],"keys":["fa556045-31f9-4bc4-a1d5-fe60e313e85e"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. This choice most effectively emphasizes how Romney wool differs from Merino and Rambouillet wool. It describes the difference in thickness and the difference in what they&rsquo;re used for.&nbsp;</p><p>Choice A is incorrect. This choice doesn&rsquo;t emphasize how Romney wool differs from Merino and Rambouillet wool. It doesn&rsquo;t mention Merino or Rambouillet wool at all.&nbsp;Choice B is incorrect. This choice doesn&rsquo;t emphasize how Romney wool differs from Merino and Rambouillet wool. It doesn&rsquo;t mention Merino or Rambouillet wool at all.&nbsp;Choice D is incorrect. This choice doesn&rsquo;t emphasize how Romney wool differs from Merino and Rambouillet wool. It doesn&rsquo;t mention Romney, Merino or Rambouillet wool at all.&nbsp;</p>","parenttemplatename":"OSP-715-SYN","parenttemplateid":"","templateclusterid":"de6e95a4-42f6-4b4a-99d8-5f2a5d43d0c1","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959348,"updateDate":1691007959348}$SATQ$::jsonb, 1691007959348, 1691007959348),
    ($SATQ$1bb4aec8$SATQ$, $SATQ$ae189755-0e72-4eb9-b900-b75332cdca37$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Meteorites found on Earth are divided into two categories.</li>
<li>A meteorite that was observed falling to Earth&nbsp;before being recovered is known as a meteorite fall.</li>
<li>All other meteorites found on Earth are known as meteorite finds.</li>
<li>There have been about 1,200 recorded meteorite falls.&nbsp;</li>
<li>There have been over 60,000 recorded meteorite finds.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to contrast the number of meteorite falls with the number of meteorite finds. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"58f275ea-8d11-4897-b78e-b8d91df5a793","content":"<p>A meteorite that was observed falling to Earth before being recovered is known as a meteorite fall; all others are known as meteorite finds.</p>"},{"id":"2d075ca5-aa14-4f4c-b856-8bfa00992e3a","content":"<p>Meteorites found on Earth are divided into two categories: meteorite falls and meteorite finds.</p>"},{"id":"f8de02ee-e766-4da4-adaf-2ef77f46bef7","content":"<p>There have been about 1,200 recorded meteorite falls, or meteorites observed falling to Earth.&nbsp;</p>"},{"id":"603c255b-3b9d-480e-8156-ba7bf906a1cb","content":"<p>While there have been only about 1,200 recorded meteorite falls, there have been over 60,000 meteorite finds.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["603c255b-3b9d-480e-8156-ba7bf906a1cb"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The sentence contrasts the number of meteorite falls with the number of meteorite finds, noting that there have been over 60,000 meteorite finds but only about 1,200 recorded meteorite falls.</p><p>Choice A is incorrect. While the sentence explains the difference between meteorite falls and meteorite finds, it doesn&rsquo;t contrast the number of meteorite falls and meteorite finds. Choice B is incorrect. The sentence indicates the two categories of meteorites found on Earth; it doesn&rsquo;t contrast the number of meteorite falls and meteorite finds. Choice C is incorrect. While the sentence notes the number of recorded meteorite falls, it doesn&rsquo;t contrast this with the number of meteorite finds.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"1bb4aec8","external_id":"ae189755-0e72-4eb9-b900-b75332cdca37","vaultid":null,"uId":"62527492-3899-4387-931c-83565d4a9632","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Meteorites found on Earth are divided into two categories.</li>\n<li>A meteorite that was observed falling to Earth&nbsp;before being recovered is known as a meteorite fall.</li>\n<li>All other meteorites found on Earth are known as meteorite finds.</li>\n<li>There have been about 1,200 recorded meteorite falls.&nbsp;</li>\n<li>There have been over 60,000 recorded meteorite finds.</li>\n</ul>","stem":"<p>The student wants to contrast the number of meteorite falls with the number of meteorite finds. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"58f275ea-8d11-4897-b78e-b8d91df5a793","content":"<p>A meteorite that was observed falling to Earth before being recovered is known as a meteorite fall; all others are known as meteorite finds.</p>"},{"id":"2d075ca5-aa14-4f4c-b856-8bfa00992e3a","content":"<p>Meteorites found on Earth are divided into two categories: meteorite falls and meteorite finds.</p>"},{"id":"f8de02ee-e766-4da4-adaf-2ef77f46bef7","content":"<p>There have been about 1,200 recorded meteorite falls, or meteorites observed falling to Earth.&nbsp;</p>"},{"id":"603c255b-3b9d-480e-8156-ba7bf906a1cb","content":"<p>While there have been only about 1,200 recorded meteorite falls, there have been over 60,000 meteorite finds.</p>"}],"keys":["603c255b-3b9d-480e-8156-ba7bf906a1cb"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The sentence contrasts the number of meteorite falls with the number of meteorite finds, noting that there have been over 60,000 meteorite finds but only about 1,200 recorded meteorite falls.</p><p>Choice A is incorrect. While the sentence explains the difference between meteorite falls and meteorite finds, it doesn&rsquo;t contrast the number of meteorite falls and meteorite finds. Choice B is incorrect. The sentence indicates the two categories of meteorites found on Earth; it doesn&rsquo;t contrast the number of meteorite falls and meteorite finds. Choice C is incorrect. While the sentence notes the number of recorded meteorite falls, it doesn&rsquo;t contrast this with the number of meteorite finds.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323033,"updateDate":1730147323033}$SATQ$::jsonb, 1730147323033, 1730147323033),
    ($SATQ$1c36e3e1$SATQ$, $SATQ$7ca2fa08-43b7-4451-b3f9-aeb60eaa0d2d$SATQ$::uuid, $SATQ$5fbe8652-ed59-4979-9f8a-b6d5755454a3$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 1, $SATQ$mcq$SATQ$, $SATQ$<p>The number of dark spots that appear on the Sun, known as sunspots, can vary greatly. For example, there were about 180 sunspots in November 2001. <span aria-hidden="true">______</span><span class="sr-only">blank</span> there were only about 2 sunspots in December 2008.</p>
<p>&nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"dcabbf01-3248-448d-a7cb-9d7db5378692","content":"<p>&nbsp;In other words,</p>"},{"id":"5ab35b15-1104-4032-a3c7-27a389fba8e0","content":"<p>Similarly,</p>"},{"id":"32b1aded-8e47-4afd-af8a-84bc0694171d","content":"<p>Therefore,</p>"},{"id":"ac6a3a5a-4488-4106-97c9-59fd4cdec81c","content":"<p>By comparison,</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["ac6a3a5a-4488-4106-97c9-59fd4cdec81c"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The first sentence claims that the number of sunspots can vary greatly. To support this claim, the next two sentences compare two examples: one time when there were 180 sunspots and one time when there were only 2 sunspots. So the transition &ldquo;by comparison&rdquo; fits perfectly. </p><p>Choice A is incorrect. This choice uses a transition that indicates a restatement of the same idea, which doesn&rsquo;t make sense here. This sentence doesn&rsquo;t restate the first example&mdash;it describes a totally different example. Choice B is incorrect. This choice uses a transition that indicates the addition of a similar idea, which doesn&rsquo;t make sense here. This sentence describes a second example that is very different from the first example. Choice C is incorrect. This choice uses a cause-and-effect transition, which doesn&rsquo;t make sense here. The first example didn&rsquo;t result in the second example. </p>$SATQ$, false, 0, $SATQ$OSP-KA-TRA-E003$SATQ$, $SATQ$$SATQ$, $SATQ$c4c31f31-c100-46c2-bb30-dda6f7baba24$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"1c36e3e1","external_id":"7ca2fa08-43b7-4451-b3f9-aeb60eaa0d2d","vaultid":"5fbe8652-ed59-4979-9f8a-b6d5755454a3","uId":"bbf6364e-a0d1-404b-89b1-83159ead2a4f","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":1,"type":"mcq","stimulus":"<p>The number of dark spots that appear on the Sun, known as sunspots, can vary greatly. For example, there were about 180 sunspots in November 2001. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> there were only about 2 sunspots in December 2008.</p>\n<p>&nbsp;</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"dcabbf01-3248-448d-a7cb-9d7db5378692","content":"<p>&nbsp;In other words,</p>"},{"id":"5ab35b15-1104-4032-a3c7-27a389fba8e0","content":"<p>Similarly,</p>"},{"id":"32b1aded-8e47-4afd-af8a-84bc0694171d","content":"<p>Therefore,</p>"},{"id":"ac6a3a5a-4488-4106-97c9-59fd4cdec81c","content":"<p>By comparison,</p>"}],"keys":["ac6a3a5a-4488-4106-97c9-59fd4cdec81c"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The first sentence claims that the number of sunspots can vary greatly. To support this claim, the next two sentences compare two examples: one time when there were 180 sunspots and one time when there were only 2 sunspots. So the transition &ldquo;by comparison&rdquo; fits perfectly. </p><p>Choice A is incorrect. This choice uses a transition that indicates a restatement of the same idea, which doesn&rsquo;t make sense here. This sentence doesn&rsquo;t restate the first example&mdash;it describes a totally different example. Choice B is incorrect. This choice uses a transition that indicates the addition of a similar idea, which doesn&rsquo;t make sense here. This sentence describes a second example that is very different from the first example. Choice C is incorrect. This choice uses a cause-and-effect transition, which doesn&rsquo;t make sense here. The first example didn&rsquo;t result in the second example. </p>","parenttemplatename":"OSP-KA-TRA-E003","parenttemplateid":"","templateclusterid":"c4c31f31-c100-46c2-bb30-dda6f7baba24","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959372,"updateDate":1691007959372}$SATQ$::jsonb, 1691007959372, 1691007959372),
    ($SATQ$1c6e1d55$SATQ$, $SATQ$161725f0-8529-45c1-bf18-5df4d261b7b5$SATQ$::uuid, $SATQ$05f82afb-da14-4564-bf4d-0d7813b4c94b$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Historically, most conductors of major orchestras and opera companies have been European men, but a new, more diverse generation of artists is stepping up to the podium. Mexico&rsquo;s Alondra de la Parra took over as conductor for the Queensland Symphony Orchestra in 2017, <span aria-hidden="true">______</span><span class="sr-only">blank</span> and Colombia&rsquo;s Lina Gonzalez-Granados did the same for the Los Angeles Opera in 2022.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"a80bb90a-29e7-4b1d-93b0-077f37692545","content":"<p>in addition,</p>"},{"id":"7c601bf8-4f6a-49f9-9660-59f8dd18e014","content":"<p>lastly,</p>"},{"id":"490e9944-79b5-406d-a440-54eeed3d924e","content":"<p>granted,</p>"},{"id":"d11d1369-413e-4fed-b0ae-cec8106f7264","content":"<p>for instance,</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["d11d1369-413e-4fed-b0ae-cec8106f7264"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. &ldquo;For instance&rdquo; logically signals that the details in this sentence&mdash;that Mexican conductor Alondra de la Parra and Colombian conductor Lina Gonzalez-Granados took new conducting positions&mdash;are examples supporting the previous claim about the new generation of artists. </p><p>Choice A is incorrect because &ldquo;in addition&rdquo; illogically signals that the details in this sentence about de la Parra and Gonzalez-Granados are merely additional facts related to the previous claim about the new generation of artists. Instead, they are examples supporting that claim. Choice B is incorrect because &ldquo;lastly&rdquo; illogically signals that the details in this sentence about de la Parra and Gonzalez-Granados are the last step or a concluding summary of the previous claim about the new generation of artists. Instead, they are examples supporting that claim. Choice C is incorrect because &ldquo;granted&rdquo; illogically signals that the details in this sentence about de la Parra and Gonzalez-Granados are exceptions to the previous claim about the new generation of artists. Instead, they are examples supporting that claim. </p>$SATQ$, false, 0, $SATQ$OSP-263-TRA$SATQ$, $SATQ$$SATQ$, $SATQ$a9f50ae8-6d7a-45af-a1df-4f0c1d167e34$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"1c6e1d55","external_id":"161725f0-8529-45c1-bf18-5df4d261b7b5","vaultid":"05f82afb-da14-4564-bf4d-0d7813b4c94b","uId":"837c31f7-2ec8-4de6-a588-a6d629494461","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Historically, most conductors of major orchestras and opera companies have been European men, but a new, more diverse generation of artists is stepping up to the podium. Mexico&rsquo;s Alondra de la Parra took over as conductor for the Queensland Symphony Orchestra in 2017, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> and Colombia&rsquo;s Lina Gonzalez-Granados did the same for the Los Angeles Opera in 2022.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"a80bb90a-29e7-4b1d-93b0-077f37692545","content":"<p>in addition,</p>"},{"id":"7c601bf8-4f6a-49f9-9660-59f8dd18e014","content":"<p>lastly,</p>"},{"id":"490e9944-79b5-406d-a440-54eeed3d924e","content":"<p>granted,</p>"},{"id":"d11d1369-413e-4fed-b0ae-cec8106f7264","content":"<p>for instance,</p>"}],"keys":["d11d1369-413e-4fed-b0ae-cec8106f7264"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. &ldquo;For instance&rdquo; logically signals that the details in this sentence&mdash;that Mexican conductor Alondra de la Parra and Colombian conductor Lina Gonzalez-Granados took new conducting positions&mdash;are examples supporting the previous claim about the new generation of artists. </p><p>Choice A is incorrect because &ldquo;in addition&rdquo; illogically signals that the details in this sentence about de la Parra and Gonzalez-Granados are merely additional facts related to the previous claim about the new generation of artists. Instead, they are examples supporting that claim. Choice B is incorrect because &ldquo;lastly&rdquo; illogically signals that the details in this sentence about de la Parra and Gonzalez-Granados are the last step or a concluding summary of the previous claim about the new generation of artists. Instead, they are examples supporting that claim. Choice C is incorrect because &ldquo;granted&rdquo; illogically signals that the details in this sentence about de la Parra and Gonzalez-Granados are exceptions to the previous claim about the new generation of artists. Instead, they are examples supporting that claim. </p>","parenttemplatename":"OSP-263-TRA","parenttemplateid":"","templateclusterid":"a9f50ae8-6d7a-45af-a1df-4f0c1d167e34","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959334,"updateDate":1691007959334}$SATQ$::jsonb, 1691007959334, 1691007959334),
    ($SATQ$1ccfcea4$SATQ$, $SATQ$6877e1d2-be1b-473d-9b82-100b215d1ddd$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>The French directors Colas Koola and Vivien Mermet-Guyenet (known as Koola and Viv) founded the video game studio BlueTwelve. They also love cats. <span aria-hidden="true">______</span><span class="sr-only">blank</span> they created an award-winning cat video game, <em>Stray</em> (2021), that lets the player explore a dystopian city from the perspective of a clever orange house cat.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"d3214ba2-b7fa-49af-b47c-f322e5f2507e","content":"<p>Intermittently,</p>"},{"id":"396cd5a3-0d8e-4641-91b2-478072e3c343","content":"<p>On the other hand,</p>"},{"id":"ab9e872e-8c1d-4dec-92bf-08ecf0f0153e","content":"<p>In fact,</p>"},{"id":"c45dcd5c-df1f-4afa-bad9-a201d486d4bd","content":"<p>Nevertheless,</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["ab9e872e-8c1d-4dec-92bf-08ecf0f0153e"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. "In fact" logically signals that the information in this sentence about the creation of the video game offers additional emphasis in support of the previous claim that video game studio founders Koola and Viv love cats.</p><p>Choice A is incorrect because "intermittently" illogically signals that the information in this sentence occurs sporadically or in intervals. Instead, the creation of the video game offers additional emphasis in support of the previous claim about Koola and Viv. Choice B is incorrect because "on the other hand" illogically signals that the information in this sentence contrasts with the previous claim about Koola and Viv. Instead, the creation of the video game offers additional emphasis in support of that claim. Choice D is incorrect because "nevertheless" illogically signals that the information in this sentence is true despite the previous claim that Koola and Viv love cats. Instead, the creation of the video game offers additional emphasis in support of that claim.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"1ccfcea4","external_id":"6877e1d2-be1b-473d-9b82-100b215d1ddd","vaultid":null,"uId":"97497102-76a7-4dcf-8074-c3e89f7458c6","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>The French directors Colas Koola and Vivien Mermet-Guyenet (known as Koola and Viv) founded the video game studio BlueTwelve. They also love cats. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> they created an award-winning cat video game, <em>Stray</em> (2021), that lets the player explore a dystopian city from the perspective of a clever orange house cat.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"d3214ba2-b7fa-49af-b47c-f322e5f2507e","content":"<p>Intermittently,</p>"},{"id":"396cd5a3-0d8e-4641-91b2-478072e3c343","content":"<p>On the other hand,</p>"},{"id":"ab9e872e-8c1d-4dec-92bf-08ecf0f0153e","content":"<p>In fact,</p>"},{"id":"c45dcd5c-df1f-4afa-bad9-a201d486d4bd","content":"<p>Nevertheless,</p>"}],"keys":["ab9e872e-8c1d-4dec-92bf-08ecf0f0153e"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. \"In fact\" logically signals that the information in this sentence about the creation of the video game offers additional emphasis in support of the previous claim that video game studio founders Koola and Viv love cats.</p><p>Choice A is incorrect because \"intermittently\" illogically signals that the information in this sentence occurs sporadically or in intervals. Instead, the creation of the video game offers additional emphasis in support of the previous claim about Koola and Viv. Choice B is incorrect because \"on the other hand\" illogically signals that the information in this sentence contrasts with the previous claim about Koola and Viv. Instead, the creation of the video game offers additional emphasis in support of that claim. Choice D is incorrect because \"nevertheless\" illogically signals that the information in this sentence is true despite the previous claim that Koola and Viv love cats. Instead, the creation of the video game offers additional emphasis in support of that claim.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323043,"updateDate":1730147323043}$SATQ$::jsonb, 1730147323043, 1730147323043),
    ($SATQ$1d79a59d$SATQ$, $SATQ$5f527608-5cc1-4525-bcc0-e04a71f57baf$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p><p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Leaders of the Province of Guatemala proclaimed independence for Central America from the Spanish Empire on September 15, <span data-ssml-say-as="date">1821</span>.</li>
<li>The accompanying Declaration of Independence was written by Honduran scholar and politician Jos&eacute; Cecilio del Valle.</li>
<li>The <span data-ssml-say-as="date">1812</span> Spanish Constitution had provided some degree of independence for Central America, but it was repealed by the Spanish king in <span data-ssml-say-as="date">1814</span>.</li>
<li>Valle, a loyal advisor to the Spanish Empire&rsquo;s administrators in Central America, had long opposed independence.</li>
<li>He changed his mind after Colonel Rafael del Riego&rsquo;s <span data-ssml-say-as="date">1820</span> revolt, which demanded the return of rights lost in <span data-ssml-say-as="date">1814</span>.</li>
</ul></p>$SATQ$, $SATQ$<p>The student wants to place the <span data-ssml-say-as="date">1821</span> Declaration of Independence in the context of Valle&rsquo;s changing political beliefs. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"bddd7554-6dd6-40ac-a5f9-b54f1403d6ea","content":"<p>Colonel Riego&rsquo;s revolt was the inspiration that Valle, a long-standing opponent of Central American independence, needed to change his political beliefs.</p>"},{"id":"21340d39-b959-446e-a4f7-314bdb9c3516","content":"<p>Long an opponent of Central American independence, Valle changed his mind after an <span data-ssml-say-as=\"date\">1820</span> revolt and wrote the <span data-ssml-say-as=\"date\">1821</span> declaration.</p>"},{"id":"1ea854db-5003-4ac4-a279-ed25b4f666fa","content":"<p>A change in Valle&rsquo;s political beliefs that occurred when the Spanish king repealed the <span data-ssml-say-as=\"date\">1812</span> constitution led to Valle writing Central America&rsquo;s Declaration of Independence.</p>"},{"id":"9e0ea7aa-8864-40e5-bdef-0df8f68eb7ee","content":"<p>The writing of Central America&rsquo;s Declaration of Independence may not have happened were it not for Colonel Riego&rsquo;s <span data-ssml-say-as=\"date\">1820</span> revolt.&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["21340d39-b959-446e-a4f7-314bdb9c3516"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. The sentence places the Declaration of Independence in the context of Valle&rsquo;s changing political beliefs, noting that Valle was long an opponent of Central American independence but changed his mind after an 1820 revolt and then wrote the Declaration of Independence in 1821.</p><p>Choice A is incorrect. The sentence states that Valle&rsquo;s political beliefs changed after Riego&rsquo;s revolt but doesn&rsquo;t indicate how these changed beliefs provide context for the 1821 Declaration of Independence. Choice C is incorrect because it misrepresents information from the notes. Valle&rsquo;s political beliefs changed after Riego&rsquo;s 1820 revolt, not when the Spanish king repealed the 1812 constitution. Choice D is incorrect. While the sentence indicates a relationship between Colonel Riego&rsquo;s 1820 revolt and Central America&rsquo;s Declaration of Independence, it doesn&rsquo;t mention Valle&rsquo;s changing political beliefs.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"1d79a59d","external_id":"5f527608-5cc1-4525-bcc0-e04a71f57baf","vaultid":null,"uId":"0fe31b07-b208-46da-923d-ca71744036b3","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p><p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Leaders of the Province of Guatemala proclaimed independence for Central America from the Spanish Empire on September 15, <span data-ssml-say-as=\"date\">1821</span>.</li>\n<li>The accompanying Declaration of Independence was written by Honduran scholar and politician Jos&eacute; Cecilio del Valle.</li>\n<li>The <span data-ssml-say-as=\"date\">1812</span> Spanish Constitution had provided some degree of independence for Central America, but it was repealed by the Spanish king in <span data-ssml-say-as=\"date\">1814</span>.</li>\n<li>Valle, a loyal advisor to the Spanish Empire&rsquo;s administrators in Central America, had long opposed independence.</li>\n<li>He changed his mind after Colonel Rafael del Riego&rsquo;s <span data-ssml-say-as=\"date\">1820</span> revolt, which demanded the return of rights lost in <span data-ssml-say-as=\"date\">1814</span>.</li>\n</ul></p>","stem":"<p>The student wants to place the <span data-ssml-say-as=\"date\">1821</span> Declaration of Independence in the context of Valle&rsquo;s changing political beliefs. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"bddd7554-6dd6-40ac-a5f9-b54f1403d6ea","content":"<p>Colonel Riego&rsquo;s revolt was the inspiration that Valle, a long-standing opponent of Central American independence, needed to change his political beliefs.</p>"},{"id":"21340d39-b959-446e-a4f7-314bdb9c3516","content":"<p>Long an opponent of Central American independence, Valle changed his mind after an <span data-ssml-say-as=\"date\">1820</span> revolt and wrote the <span data-ssml-say-as=\"date\">1821</span> declaration.</p>"},{"id":"1ea854db-5003-4ac4-a279-ed25b4f666fa","content":"<p>A change in Valle&rsquo;s political beliefs that occurred when the Spanish king repealed the <span data-ssml-say-as=\"date\">1812</span> constitution led to Valle writing Central America&rsquo;s Declaration of Independence.</p>"},{"id":"9e0ea7aa-8864-40e5-bdef-0df8f68eb7ee","content":"<p>The writing of Central America&rsquo;s Declaration of Independence may not have happened were it not for Colonel Riego&rsquo;s <span data-ssml-say-as=\"date\">1820</span> revolt.&nbsp;</p>"}],"keys":["21340d39-b959-446e-a4f7-314bdb9c3516"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. The sentence places the Declaration of Independence in the context of Valle&rsquo;s changing political beliefs, noting that Valle was long an opponent of Central American independence but changed his mind after an 1820 revolt and then wrote the Declaration of Independence in 1821.</p><p>Choice A is incorrect. The sentence states that Valle&rsquo;s political beliefs changed after Riego&rsquo;s revolt but doesn&rsquo;t indicate how these changed beliefs provide context for the 1821 Declaration of Independence. Choice C is incorrect because it misrepresents information from the notes. Valle&rsquo;s political beliefs changed after Riego&rsquo;s 1820 revolt, not when the Spanish king repealed the 1812 constitution. Choice D is incorrect. While the sentence indicates a relationship between Colonel Riego&rsquo;s 1820 revolt and Central America&rsquo;s Declaration of Independence, it doesn&rsquo;t mention Valle&rsquo;s changing political beliefs.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1776362771169,"updateDate":1776362771169}$SATQ$::jsonb, 1776362771169, 1776362771169),
    ($SATQ$1e31470f$SATQ$, $SATQ$df76975a-66c8-4cfc-b5fe-e06b2abc542c$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>To perform a quad axel, a figure skater must leap into the air and complete four and a half rotations before landing, an extreme feat. <span aria-hidden="true">______</span><span class="sr-only">blank</span> in 2022, when 17-year-old Ilia Malinin landed the first quad axel&mdash;considered the most difficult quad jump&mdash;in a high-level competition, the audience was left awestruck.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"e343c1ab-047b-4b17-9b3f-71e3215340c7","content":"<p>Moreover,</p>"},{"id":"38a5271d-f83d-4787-852e-fb92d9446d26","content":"<p>Fittingly,</p>"},{"id":"8f463a06-d0bc-44fb-ae7d-582bbf9a3bb0","content":"<p>Next,</p>"},{"id":"5d281a78-e24f-4924-a00b-9b8430bc1392","content":"<p>However,</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["38a5271d-f83d-4787-852e-fb92d9446d26"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. "Fittingly" logically signals that the information in this sentence&mdash;that the audience was amazed when Malinin landed the first quad axel&mdash;describes a suitable or appropriate reaction to the completion of this extremely difficult jump.</p><p>Choice A is incorrect. "Moreover" illogically signals that the information in this sentence merely adds to the previous information about the difficulty of completing a quad axel. Instead, the audience&rsquo;s amazement is a suitable or appropriate reaction to this accomplishment. Choice C is incorrect. "Next" illogically signals that the information in this sentence is simply the next step in a process. Instead, the audience&rsquo;s amazement is a suitable or appropriate reaction to the accomplishment. Choice D is incorrect. "However" illogically signals that the information in this sentence is in contrast or an exception to the difficulty of completing a quad axel. Instead, the audience&rsquo;s amazement is a suitable or appropriate reaction to this accomplishment.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"1e31470f","external_id":"df76975a-66c8-4cfc-b5fe-e06b2abc542c","vaultid":null,"uId":"95b53fd9-af08-4a8f-951d-660fbb0689d1","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>To perform a quad axel, a figure skater must leap into the air and complete four and a half rotations before landing, an extreme feat. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> in 2022, when 17-year-old Ilia Malinin landed the first quad axel&mdash;considered the most difficult quad jump&mdash;in a high-level competition, the audience was left awestruck.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"e343c1ab-047b-4b17-9b3f-71e3215340c7","content":"<p>Moreover,</p>"},{"id":"38a5271d-f83d-4787-852e-fb92d9446d26","content":"<p>Fittingly,</p>"},{"id":"8f463a06-d0bc-44fb-ae7d-582bbf9a3bb0","content":"<p>Next,</p>"},{"id":"5d281a78-e24f-4924-a00b-9b8430bc1392","content":"<p>However,</p>"}],"keys":["38a5271d-f83d-4787-852e-fb92d9446d26"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. \"Fittingly\" logically signals that the information in this sentence&mdash;that the audience was amazed when Malinin landed the first quad axel&mdash;describes a suitable or appropriate reaction to the completion of this extremely difficult jump.</p><p>Choice A is incorrect. \"Moreover\" illogically signals that the information in this sentence merely adds to the previous information about the difficulty of completing a quad axel. Instead, the audience&rsquo;s amazement is a suitable or appropriate reaction to this accomplishment. Choice C is incorrect. \"Next\" illogically signals that the information in this sentence is simply the next step in a process. Instead, the audience&rsquo;s amazement is a suitable or appropriate reaction to the accomplishment. Choice D is incorrect. \"However\" illogically signals that the information in this sentence is in contrast or an exception to the difficulty of completing a quad axel. Instead, the audience&rsquo;s amazement is a suitable or appropriate reaction to this accomplishment.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323044,"updateDate":1730147323044}$SATQ$::jsonb, 1730147323044, 1730147323044),
    ($SATQ$20733eac$SATQ$, $SATQ$4b78a030-0743-4f15-a598-429916cd6ecc$SATQ$::uuid, $SATQ$d6f0fe62-febf-4ab1-bd45-bf4bd7b4612d$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>It has long been thought that humans first crossed a land bridge into the Americas approximately 13,000 years ago. <span aria-hidden="true">______</span><span class="sr-only">blank</span> based on radiocarbon dating of samples uncovered in Mexico, a research team recently suggested that humans may have arrived more than 30,000 years ago&mdash;much earlier than previously thought.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"843d0926-82c4-4c8a-8af5-0b3ed1027fd6","content":"<p>As a result,</p>"},{"id":"e86a7cc3-7f20-4dae-9e36-76eb981a10f5","content":"<p>Similarly,</p>"},{"id":"57ed9581-97a1-408a-b359-eb3f5cffd01e","content":"<p>However,</p>"},{"id":"b13bdc0b-da1f-419b-9100-f65e853e41f9","content":"<p>In conclusion,&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["C"]$SATQ$::jsonb, $SATQ$["57ed9581-97a1-408a-b359-eb3f5cffd01e"]$SATQ$::jsonb, $SATQ$<p>Choice C is the best answer. &ldquo;However&rdquo; logically signals that the theory discussed in this sentence&mdash;that humans may have arrived in the Americas over 30,000 years ago&mdash;contrasts with the previously discussed theory that humans arrived around 13,000 years ago. </p><p>Choice A is incorrect because &ldquo;as a result&rdquo; illogically signals that the theory in this sentence is the result of the theory discussed in the previous sentence. Instead, this theory contrasts with the previous one. Choice B is incorrect because &ldquo;similarly&rdquo; illogically signals that the theory in this sentence is similar to the theory discussed in the previous sentence. Instead, this theory contrasts with the previous one. Choice D is incorrect because &ldquo;in conclusion&rdquo; illogically signals that the theory in this sentence concludes or summarizes the discussion of the previous theory. Instead, this theory contrasts with the previous one. </p>$SATQ$, false, 0, $SATQ$OSP-KA-TRA-E002$SATQ$, $SATQ$$SATQ$, $SATQ$6bb68e9b-c2a0-4a05-a50b-a998c014f428$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"20733eac","external_id":"4b78a030-0743-4f15-a598-429916cd6ecc","vaultid":"d6f0fe62-febf-4ab1-bd45-bf4bd7b4612d","uId":"162320d7-b1cb-45f6-a189-5a5ce254aeec","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>It has long been thought that humans first crossed a land bridge into the Americas approximately 13,000 years ago. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> based on radiocarbon dating of samples uncovered in Mexico, a research team recently suggested that humans may have arrived more than 30,000 years ago&mdash;much earlier than previously thought.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"843d0926-82c4-4c8a-8af5-0b3ed1027fd6","content":"<p>As a result,</p>"},{"id":"e86a7cc3-7f20-4dae-9e36-76eb981a10f5","content":"<p>Similarly,</p>"},{"id":"57ed9581-97a1-408a-b359-eb3f5cffd01e","content":"<p>However,</p>"},{"id":"b13bdc0b-da1f-419b-9100-f65e853e41f9","content":"<p>In conclusion,&nbsp;</p>"}],"keys":["57ed9581-97a1-408a-b359-eb3f5cffd01e"],"correct_answer":["C"],"rationale":"<p>Choice C is the best answer. &ldquo;However&rdquo; logically signals that the theory discussed in this sentence&mdash;that humans may have arrived in the Americas over 30,000 years ago&mdash;contrasts with the previously discussed theory that humans arrived around 13,000 years ago. </p><p>Choice A is incorrect because &ldquo;as a result&rdquo; illogically signals that the theory in this sentence is the result of the theory discussed in the previous sentence. Instead, this theory contrasts with the previous one. Choice B is incorrect because &ldquo;similarly&rdquo; illogically signals that the theory in this sentence is similar to the theory discussed in the previous sentence. Instead, this theory contrasts with the previous one. Choice D is incorrect because &ldquo;in conclusion&rdquo; illogically signals that the theory in this sentence concludes or summarizes the discussion of the previous theory. Instead, this theory contrasts with the previous one. </p>","parenttemplatename":"OSP-KA-TRA-E002","parenttemplateid":"","templateclusterid":"6bb68e9b-c2a0-4a05-a50b-a998c014f428","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959372,"updateDate":1691007959372}$SATQ$::jsonb, 1691007959372, 1691007959372),
    ($SATQ$20e4ff59$SATQ$, $SATQ$6af3a60c-c170-491d-be9d-115216ff8068$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>Famous for its four-degree tilt, the leaning Garisenda Tower is a popular attraction in Bologna&rsquo;s city center. However, measurements taken in 2023 showed that the tower was rotating in a concerning way. <span aria-hidden="true">______</span><span class="sr-only">blank</span> city officials closed the area around the tower so experts could explore solutions to stabilize the historical twelfth-century structure.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"7ed15e58-b1ad-4fd3-be44-3f4f304b2c4b","content":"<p>Similarly,</p>"},{"id":"4ca2af0f-9d08-4a4f-ae1e-ff8b481c5441","content":"<p>As a result,</p>"},{"id":"9ed39215-c711-4ffe-87dc-a9ab16a78532","content":"<p>For example,</p>"},{"id":"c63d7e40-6cbf-4457-929e-74c5e11ca154","content":"<p>In comparison,</p>"}]$SATQ$::jsonb, $SATQ$["B"]$SATQ$::jsonb, $SATQ$["4ca2af0f-9d08-4a4f-ae1e-ff8b481c5441"]$SATQ$::jsonb, $SATQ$<p>Choice B is the best answer. "As a result" logically signals that the action described in this sentence&mdash;closing the area around Garisenda Tower to explore stabilization solutions&mdash;occurred as a consequence or result of measurements revealing the tower&rsquo;s concerning rotation.</p><p>Choice A is incorrect because "similarly" illogically signals that the action of closing the tower area is similar to the discovery of concerning rotation described in the previous sentence. Instead, closing the area around the tower to explore solutions occurred as a result of the measurements revealing the rotation. Choice C is incorrect because "for example" illogically signals that the action of closing the tower area serves as an example of the tower&rsquo;s concerning rotation described in the previous sentence. Instead, closing the area around the tower to explore solutions occurred as a result of the measurements revealing the rotation. Choice D is incorrect because "in comparison" illogically signals that the action of closing the tower area is being compared to the discovery of concerning rotation described in the previous sentence. Instead, closing the area around the tower to explore solutions occurred as a result of the measurements revealing the rotation.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"20e4ff59","external_id":"6af3a60c-c170-491d-be9d-115216ff8068","vaultid":null,"uId":"54776cf4-f1ff-4f0b-b08c-705ea421e169","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>Famous for its four-degree tilt, the leaning Garisenda Tower is a popular attraction in Bologna&rsquo;s city center. However, measurements taken in 2023 showed that the tower was rotating in a concerning way. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> city officials closed the area around the tower so experts could explore solutions to stabilize the historical twelfth-century structure.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"7ed15e58-b1ad-4fd3-be44-3f4f304b2c4b","content":"<p>Similarly,</p>"},{"id":"4ca2af0f-9d08-4a4f-ae1e-ff8b481c5441","content":"<p>As a result,</p>"},{"id":"9ed39215-c711-4ffe-87dc-a9ab16a78532","content":"<p>For example,</p>"},{"id":"c63d7e40-6cbf-4457-929e-74c5e11ca154","content":"<p>In comparison,</p>"}],"keys":["4ca2af0f-9d08-4a4f-ae1e-ff8b481c5441"],"correct_answer":["B"],"rationale":"<p>Choice B is the best answer. \"As a result\" logically signals that the action described in this sentence&mdash;closing the area around Garisenda Tower to explore stabilization solutions&mdash;occurred as a consequence or result of measurements revealing the tower&rsquo;s concerning rotation.</p><p>Choice A is incorrect because \"similarly\" illogically signals that the action of closing the tower area is similar to the discovery of concerning rotation described in the previous sentence. Instead, closing the area around the tower to explore solutions occurred as a result of the measurements revealing the rotation. Choice C is incorrect because \"for example\" illogically signals that the action of closing the tower area serves as an example of the tower&rsquo;s concerning rotation described in the previous sentence. Instead, closing the area around the tower to explore solutions occurred as a result of the measurements revealing the rotation. Choice D is incorrect because \"in comparison\" illogically signals that the action of closing the tower area is being compared to the discovery of concerning rotation described in the previous sentence. Instead, closing the area around the tower to explore solutions occurred as a result of the measurements revealing the rotation.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669208,"updateDate":1743430669208}$SATQ$::jsonb, 1743430669208, 1743430669208),
    ($SATQ$221ecf0f$SATQ$, $SATQ$63f8c428-d75b-4220-a71a-2a7998892f80$SATQ$::uuid, $SATQ$22a8e046-4173-45df-b81c-298236f7a144$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$TRA$SATQ$, $SATQ$Transitions$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>Alexander Lawrence Posey (1873&ndash;1908) varied his focus and tone depending on the genre in which he was writing. In his poetry, he used heartfelt language to evoke the beauty and peacefulness of his natural surroundings; in his journalism, <span aria-hidden="true">______</span><span class="sr-only">blank</span> he employed humor and satire to comment on political issues affecting his Muskogee Creek community.</p>$SATQ$, $SATQ$<p>Which choice completes the text with the most logical transition?</p>$SATQ$, $SATQ$[{"id":"136de6aa-1b8f-4c3c-ae17-6845b76d5c14","content":"<p>that is,</p>"},{"id":"a745d675-262a-41e2-89b6-415269ea7ce4","content":"<p>granted,</p>"},{"id":"0d306405-4b82-4429-83f8-1e5475ab13bc","content":"<p>similarly,</p>"},{"id":"42a23152-ebaf-4f27-bc82-4037f379f628","content":"<p>by contrast,</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["42a23152-ebaf-4f27-bc82-4037f379f628"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. This sentence compares two examples of Posey&rsquo;s tone: the &ldquo;heartfelt language&rdquo; he used in his poetry versus the &ldquo;humor and satire&rdquo; he used in his journalism. We know from these descriptions and from the claim in the previous sentence that the two tones are very different from each other. So the transition &ldquo;by contrast&rdquo; fits the context perfectly. </p><p>Choice A is incorrect. This choice uses a transition that indicates a restatement of the same idea in other words. But the text isn&rsquo;t restating the first example here. Instead, it&rsquo;s offering a second, totally different example. Choice B is incorrect. This choice uses a transition that means &ldquo;admittedly.&rdquo; But the text isn&rsquo;t admitting or conceding anything here. Instead, these two examples work together to support the claim made in the first sentence. Choice C is incorrect. This choice uses a transition that indicates the addition of an agreeing idea. But these two examples are intentionally very different from each other, so &ldquo;similarly&rdquo; doesn&rsquo;t make sense here. </p>$SATQ$, false, 0, $SATQ$OSP-KA-TRA-M003$SATQ$, $SATQ$$SATQ$, $SATQ$d46ace20-6ee0-4bfe-a9c1-572c3a88b220$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"221ecf0f","external_id":"63f8c428-d75b-4220-a71a-2a7998892f80","vaultid":"22a8e046-4173-45df-b81c-298236f7a144","uId":"1fcdcfe6-5894-4520-98c3-f6b429985a30","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"TRA","skill_desc":"Transitions","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>Alexander Lawrence Posey (1873&ndash;1908) varied his focus and tone depending on the genre in which he was writing. In his poetry, he used heartfelt language to evoke the beauty and peacefulness of his natural surroundings; in his journalism, <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> he employed humor and satire to comment on political issues affecting his Muskogee Creek community.</p>","stem":"<p>Which choice completes the text with the most logical transition?</p>","answerOptions":[{"id":"136de6aa-1b8f-4c3c-ae17-6845b76d5c14","content":"<p>that is,</p>"},{"id":"a745d675-262a-41e2-89b6-415269ea7ce4","content":"<p>granted,</p>"},{"id":"0d306405-4b82-4429-83f8-1e5475ab13bc","content":"<p>similarly,</p>"},{"id":"42a23152-ebaf-4f27-bc82-4037f379f628","content":"<p>by contrast,</p>"}],"keys":["42a23152-ebaf-4f27-bc82-4037f379f628"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. This sentence compares two examples of Posey&rsquo;s tone: the &ldquo;heartfelt language&rdquo; he used in his poetry versus the &ldquo;humor and satire&rdquo; he used in his journalism. We know from these descriptions and from the claim in the previous sentence that the two tones are very different from each other. So the transition &ldquo;by contrast&rdquo; fits the context perfectly. </p><p>Choice A is incorrect. This choice uses a transition that indicates a restatement of the same idea in other words. But the text isn&rsquo;t restating the first example here. Instead, it&rsquo;s offering a second, totally different example. Choice B is incorrect. This choice uses a transition that means &ldquo;admittedly.&rdquo; But the text isn&rsquo;t admitting or conceding anything here. Instead, these two examples work together to support the claim made in the first sentence. Choice C is incorrect. This choice uses a transition that indicates the addition of an agreeing idea. But these two examples are intentionally very different from each other, so &ldquo;similarly&rdquo; doesn&rsquo;t make sense here. </p>","parenttemplatename":"OSP-KA-TRA-M003","parenttemplateid":"","templateclusterid":"d46ace20-6ee0-4bfe-a9c1-572c3a88b220","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959373,"updateDate":1691007959373}$SATQ$::jsonb, 1691007959373, 1691007959373),
    ($SATQ$23da9791$SATQ$, $SATQ$e2a04a2f-1b77-450f-8d40-6adb9294ce88$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Expression of Ideas$SATQ$, $SATQ$EOI$SATQ$, $SATQ$SYN$SATQ$, $SATQ$Rhetorical Synthesis$SATQ$, $SATQ$M$SATQ$, 4, $SATQ$mcq$SATQ$, $SATQ$<p>While researching a topic, a student has taken the following notes:</p>
<ul>
<li>Scientists have long sought to determine the origin of glass in Chile&rsquo;s Atacama Desert.</li>
<li>A 2017 study concluded that ancient grass fires had melted the area&rsquo;s sandy soil into glass.</li>
<li>In 2021, a different study revealed that the mineral signatures of glass samples were consistent with the mineral signatures of comet samples collected by NASA.</li>
<li>That study concluded that the glass had formed as a result of a cometary explosion close to the desert&rsquo;s surface.</li>
</ul>$SATQ$, $SATQ$<p>The student wants to describe how scientific understanding about the glass&rsquo;s origin has evolved. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>$SATQ$, $SATQ$[{"id":"ce478a92-1891-44c8-8b0d-5501dcb24fdd","content":"<p>Scientists have long sought to determine the origin of the glass, with one study concluding that it formed when ancient grass fires melted the area&rsquo;s sandy soil.</p>"},{"id":"e2261361-2bc9-4f44-bba3-cbfbc8b69518","content":"<p>Studies in 2017 and 2021 offered different explanations for the origin of the glass.&nbsp;</p>"},{"id":"31c2fb70-229e-42f8-9e5f-6f6f3c261b54","content":"<p>Mineral signatures of glass samples are consistent with those of comet samples collected by NASA, according to new research.</p>"},{"id":"d0dd20e2-44cf-483a-8ecb-de96f6e048d7","content":"<p>A 2017 study concluded that ancient grass fires had caused the glass&rsquo;s formation, but new research suggests that the glass formed as a result of a cometary explosion close to the desert&rsquo;s surface.</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["d0dd20e2-44cf-483a-8ecb-de96f6e048d7"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The sentence describes how scientific understanding of the glass&rsquo;s origin has evolved, explaining that new research suggests the glass formed as a result of a cometary explosion instead of being caused by grass fires (as was previously believed).</p><p>Choice A is incorrect. The sentence explains the conclusion of the older study; it doesn&rsquo;t describe how scientific understanding of the glass&rsquo;s origin has evolved. Choice B is incorrect. While the sentence indicates that the two studies provided different explanations, it doesn&rsquo;t describe how scientific understanding of the glass&rsquo;s origin has evolved. Choice C is incorrect. The sentence references a recent finding but doesn&rsquo;t effectively describe how scientific understanding of the glass&rsquo;s origin has evolved.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"23da9791","external_id":"e2a04a2f-1b77-450f-8d40-6adb9294ce88","vaultid":null,"uId":"40bb9277-a758-4f2d-98ff-59af3575a916","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"EOI","domain":"Expression of Ideas","skill_cd":"SYN","skill_desc":"Rhetorical Synthesis","difficulty":"M","score_band_range_cd":4,"type":"mcq","stimulus":"<p>While researching a topic, a student has taken the following notes:</p>\n<ul>\n<li>Scientists have long sought to determine the origin of glass in Chile&rsquo;s Atacama Desert.</li>\n<li>A 2017 study concluded that ancient grass fires had melted the area&rsquo;s sandy soil into glass.</li>\n<li>In 2021, a different study revealed that the mineral signatures of glass samples were consistent with the mineral signatures of comet samples collected by NASA.</li>\n<li>That study concluded that the glass had formed as a result of a cometary explosion close to the desert&rsquo;s surface.</li>\n</ul>","stem":"<p>The student wants to describe how scientific understanding about the glass&rsquo;s origin has evolved. Which choice most effectively uses relevant information from the notes to accomplish this goal?</p>","answerOptions":[{"id":"ce478a92-1891-44c8-8b0d-5501dcb24fdd","content":"<p>Scientists have long sought to determine the origin of the glass, with one study concluding that it formed when ancient grass fires melted the area&rsquo;s sandy soil.</p>"},{"id":"e2261361-2bc9-4f44-bba3-cbfbc8b69518","content":"<p>Studies in 2017 and 2021 offered different explanations for the origin of the glass.&nbsp;</p>"},{"id":"31c2fb70-229e-42f8-9e5f-6f6f3c261b54","content":"<p>Mineral signatures of glass samples are consistent with those of comet samples collected by NASA, according to new research.</p>"},{"id":"d0dd20e2-44cf-483a-8ecb-de96f6e048d7","content":"<p>A 2017 study concluded that ancient grass fires had caused the glass&rsquo;s formation, but new research suggests that the glass formed as a result of a cometary explosion close to the desert&rsquo;s surface.</p>"}],"keys":["d0dd20e2-44cf-483a-8ecb-de96f6e048d7"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The sentence describes how scientific understanding of the glass&rsquo;s origin has evolved, explaining that new research suggests the glass formed as a result of a cometary explosion instead of being caused by grass fires (as was previously believed).</p><p>Choice A is incorrect. The sentence explains the conclusion of the older study; it doesn&rsquo;t describe how scientific understanding of the glass&rsquo;s origin has evolved. Choice B is incorrect. While the sentence indicates that the two studies provided different explanations, it doesn&rsquo;t describe how scientific understanding of the glass&rsquo;s origin has evolved. Choice C is incorrect. The sentence references a recent finding but doesn&rsquo;t effectively describe how scientific understanding of the glass&rsquo;s origin has evolved.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323048,"updateDate":1730147323048}$SATQ$::jsonb, 1730147323048, 1730147323048)
